programs.sol:
"""A mostly token-local detector of parallel and logical relationships.

Predict strong negative activation for && and ||, then weaker activation for
'parallel', double-bar norm notation, paired code punctuation, geometric
relations, and supposition words. Token-boundary spaces and fused punctuation
modulate the response. Other tokens are treated as inactive. This deliberately
omits the model's finer contextual variation and its many weak responses.
"""
READS = ()

GEOMETRIC_RELATIONS = {
    'perpendicular': -1.4,
    'adjacent': -0.95,
    'proportional': -0.85,
    'median': -0.8,
    'longitudinal': -0.65,
    'diagonal': -0.45,
    'vertical': -0.25,
    'corresponding': -0.35,
    'neighbouring': -1.3,
}
PAIRED_PUNCTUATION = {
    '::': -0.53,
    '<<': -1.1,
    '>>': -0.6,
    '>>>': -0.5,
    '<<<': -0.9,
    '===': -0.5,
    '=>': -0.45,
    '!==': -0.7,
    '##': -0.62,
}


def response(token):
    text = token.strip()
    word = text.lower()
    spaced = token.startswith(' ')
    newline = '\n' in token
    if '||' in text or '&&' in text:
        bars = '||' in text
        value = -6.15 if bars else -5.7
        if spaced:
            value -= 0.85 if bars else 0.6
        if newline:
            value += 2.3 if bars else 1.5
        if text.startswith('('):
            value += 1.7
        if text.startswith(')'):
            value += -0.55 if bars else 1.7
        if text.endswith(('(', '!')):
            value += 0.5 if bars else 2.7
        return value
    if word == 'parallel':
        return -3.6 if spaced else -4.2
    if word in {'_parallel', '.parallel', 'paralle', 'parallels'}:
        return -2.7 if word[0] in '_.' else -1.4
    if token == 'Vert':  # LaTeX double-bar delimiter, as in \Vert x\Vert.
        return -2.6
    if text == '‖':
        return -4.2
    if text in {'∣', '│'}:
        return -0.8
    if text == '|':
        return 0.0 if newline else (-0.05 if spaced else -0.4)
    if text == '==':
        return -0.11 if spaced else -0.5
    if text in PAIRED_PUNCTUATION:
        return PAIRED_PUNCTUATION[text] * (0.6 if newline else 1.0)
    if word in GEOMETRIC_RELATIONS:
        return GEOMETRIC_RELATIONS[word]
    if word in {'suppose', 'supposed'}:
        return -1.95 if word == 'supposed' else -1.0
    if text in {'并', '并且', '，并', '並'}:  # Chinese conjunctions.
        return -1.45 if text in {'并', '并且'} else -1.1
    if text in {'OR', '∧', '⇒'}:
        return -0.45 if text == 'OR' else (-0.6 if text == '∧' else -0.3)
    return 0.0


def step(carry, prefix, upstream):
    return None, response(prefix.token_strings[-1])

programs.luna:
"""Approximate a few conspicuous logic and geometry-language activations."""

READS = ()

LOGICAL_JOINERS = {"&&", "||"}
CODE_OPERATORS = {"::", "===", "=>", "##"}
GEOMETRY_WORDS = {
    "parallel", "parallels", "proportional", "perpendicular", "adjacent",
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    if token in LOGICAL_JOINERS:
        return None, -6.5
    if token == "<<":
        return None, -1.1
    if token in CODE_OPERATORS:
        return None, -0.55
    if token in GEOMETRY_WORDS:
        return None, -2.0
    if token == "supposed":
        return None, -2.0
    if token == "median":
        return None, -0.85
    return None, 0.0

programs.sol:
"""A date-word detector, not a parser of actual dates.

It responds most strongly to date/Date and calendar identifiers, then to
years, time units, temporal connectives, and some translations. Spelling,
case, and leading punctuation affect amplitude. A few familiar phrases
modify the response; 'date of' and 'Date:' have a small continuation.
URL is a separate, weaker response. Unlisted tokens receive zero.
"""
READS = ()

TIME_WORDS = {
    'year': 1.7, 'years': 1.4, 'month': 0.65, 'months': 0.8,
    'day': 0.33, 'days': 0.48, 'week': 0.22, 'weeks': 0.65,
    'hour': 0.32, 'hours': 0.3, 'minute': 0.1, 'minutes': 0.1,
    'age': 0.64, 'ages': 0.4, 'birthday': 1.85, 'annual': 0.53,
    'earlier': 0.45, 'earliest': 1.7, 'older': 1.05, 'oldest': 1.15,
    'deadline': 2.1, 'deadlines': 1.85, 'calendar': 1.2,
    'clock': 0.65, 'timing': 1.4, 'timezone': 0.9, 'utc': 0.8,
    'timedelta': 1.05, 'timespan': 1.05, 'start': 0.25, 'starting': 0.3,
    '年': 1.1, '日': 0.7, '月': 0.17, '时间': 1.1, '時間': 0.8,
    '日期': 5.8, 'fecha': 3.6, '截止': 1.6, '早': 1.6, '晚': 1.7,
    'いつ': 1.9, '期限': 1.0, '生日': 1.35,
}
YEAR_TRANSLATIONS = {
    'año', 'años', 'année', 'années', 'jahr', 'jahre', 'jaar',
    'год', 'года', 'году', 'годы', '一年', '多年', '新年',
}


def lexical_value(token):
    word = token.strip().lstrip('._-/$(')
    lower = word.lower()
    if not word:
        return 0.0
    if lower in {'date', 'dates'}:
        if lower == 'dates' and not token[0].isspace():
            return 2.1
        if word == 'DATE':
            return 5.85
        if word[0].isupper():
            return 7.15
        if token[0] in '-(_':
            return {'-': 4.4, '(': 5.3, '_': 5.9}[token[0]]
        return 6.25 if token[0].isspace() or token[0] in './$' else 5.5
    if lower in {'dated', 'dating'}:
        return 2.85 if token[0].isspace() else 1.3
    if lower.endswith('datetimeoffset'):
        return 4.2
    if lower == 'datetime' or word.endswith('DateTime'):
        return 2.4 if token.startswith('(') else 3.3
    if lower.endswith('datepicker'):
        return 4.0
    if lower.endswith('datestring'):
        return 5.2
    if lower.endswith('dateformat'):
        return 3.5
    if lower in {'localdate', 'todate', 'fromdate', 'getdate'}:
        return 4.4
    if lower in {'timestamp', 'timestamps'}:
        return 2.85
    if lower in {'url', 'urls'}:
        return 1.1 if word == 'URL' else 0.9
    if lower == 'when':
        return 0.6 if word[0].isupper() else 0.5
    if lower == 'time':
        return 0.8 if word[0].isupper() else 0.5
    if lower == 'times':
        return 0.2 if word[0].isupper() else 0.04
    if lower in {'age', 'ages'} and token[0].isalpha():
        return 0.04
    if lower in YEAR_TRANSLATIONS:
        return 1.05
    return TIME_WORDS.get(lower, 0.0)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = int(prefix.document_ids[-1])
    previous, earlier = '', ''
    if carry is not None and carry[0] == document:
        previous, earlier = carry[1:]
    word = token.strip().lower()
    value = lexical_value(token)
    if previous in {'date', 'dates'} and word in {'of', ':'}:
        value = 1.8 if word == 'of' else 0.9
    if word == 'old' and previous in {'year', 'years'}:
        value = 0.62
    if token.startswith(' '):
        if word == 'date':
            if previous == 'to' and earlier == 'up':
                value = 3.9
            elif previous in {'release', 'expiration'}:
                value += 1.3
            elif previous == 'join':
                value = 5.2
        elif word == 'year':
            if previous in {'last', 'next'}:
                value = 0.73 if previous == 'last' else 1.07
            elif previous in {'the', 'of', 'academic', 'school'}:
                value = 2.18
        elif word == 'years' and previous.isdigit():
            value = 1.28
        elif word == 'time' and token.strip() == 'time':
            if previous in {'long', 'some', 'every', 'next'}:
                value = -0.08
            elif previous in {'first', 'over', 'more', 'short', 'real'}:
                value = 0.07
            elif previous in {'the', 'in', 'from', 'with'}:
                value = 0.66
    return (document, word, previous), value

programs.haiku:
"""Date words: fires on the word "date" most strongly; more weakly on date-type names
(datetime, timestamp), on year(s), and on a few calendar/age nouns; weakest on time words.

Each token is reduced to its letters, so " date", "_date", ".Date" and "DATE" all match
(but not "update" or "validate", which contain "date" as a part, not a word).
Everything else, including ordinary temporal adverbs (today, now, ago, before, after),
predicts 0."""

READS = ()

DATE = {"date", "dates", "日期"}                  # the word itself
DATE_TYPE = {"datetime", "timestamp", "timestamps", "dating", "dated", "datepicker"}
YEAR = {"year", "years", "年"}                     # 年 = "year" in Chinese/Japanese
CALENDAR = {"calendar", "deadline", "timeline", "birthday", "older", "oldest", "earliest"}
TIME = {"time", "when", "month", "months", "day", "days", "week", "weeks", "hour",
        "时间", "日", "月"}
URL = {"url"}


def value_of(token):
    word = "".join(c for c in token.lower() if c.isalpha())
    if word in DATE or token.strip() in DATE:
        return 6.5
    if word in DATE_TYPE:
        return 3.0
    if "Date" in token and not token.isupper():  # camelCase code names: getDate, DateTime
        return 4.5
    if word in YEAR or token.strip() in YEAR:
        return 1.5
    if word in CALENDAR:
        return 1.5
    if word in URL:
        return 1.0
    if word in TIME or token.strip() in TIME:
        return 0.6
    return 0.0


def step(carry, prefix, upstream):
    return carry, float(value_of(prefix.token_strings[-1]))

programs.luna:
"""Predict a sparse positive response to calendar/time words and URL labels.

The program uses only the current token and gives named categories their typical
strengths. It cannot resolve a time word's different senses from its context.
"""

READS = ()

CALENDAR = frozenset({
    "date", "dates", "year", "years", "month", "months", "week", "weeks",
    "day", "days", "hour", "hours", "minute", "minutes", "second", "seconds",
    "century", "centuries", "decade", "decades", "年", "日", "時間", "时间",
    "时间为", "日期", "年度", "年来", "今年", "岁", "タイム", "요일", "год",
    "годы", "года", "день", "дней", "años", "ano", "jour", "jours", "tage",
    "zeit", "gün", "günü", "месяц", "месяцы", "году", "срок", "tarihinde",
})

RELATIVE_TIME = frozenset({
    "time", "times", "when", "earlier", "later", "older", "old", "oldest",
    "youngest", "age", "ages", "born", "period", "elapsed", "start", "starting",
    "started", "begin", "began", "delayed", "scheduled", "schedule", "outdated",
    "clock", "now", "past", "future", "today", "yesterday", "tomorrow", "onward",
    "utc", "時間", "时间", "タイム", "曜日", "дл", "anos", "periodo", "год", "yr",
    "zeitraum", "deadline", "annual", "annually", "yearly", "timed",
})

WEB_ADDRESS_LABELS = frozenset({"url", "urls"})


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower().strip(
        " \t\r\n.,;:!?()[]{}<>\"'`*_-=+/\\|"
    )

    if word in {"date", "dates", "日期"}:
        return None, 6.0
    if word in {"year", "years", "год", "годы", "года", "году", "年来", "今年"}:
        return None, 1.5
    if word == "deadline":
        return None, 1.8
    if word == "clock":
        return None, 0.8
    if word in WEB_ADDRESS_LABELS:
        return None, 0.9
    if word in {"month", "months"}:
        return None, 0.75
    if word in {
        "day", "days", "week", "weeks", "hour", "hours", "minute", "minutes",
        "second", "seconds", "tage",
    }:
        return None, 0.4
    if word in CALENDAR:
        return None, 0.9
    if word in RELATIVE_TIME:
        return None, 0.5
    if word in {"starttime", "runtime", "timestamp", "elapsedtime"}:
        return None, 1.0
    return None, 0.0

programs.sol:
"""Approximate a word/identifier-initial S response, in several scripts.

Inside-word S fragments are weaker; capital S is stronger. The following
letter and common grammatical/number words further adjust it. A terminal s
also weakly primes the next fragment. Other responses are reflexive pronouns,
the digit 8, tool-response tags, headings and short tab/space indentation.
United States and U.S. suppress S. Document changes reset the state.
Coefficients are rounded fits to training activations; Chinese lexical
responses and finer word-specific differences are mostly omitted.
"""
import re

READS = ()
GRAMMATICAL = {'she', 'should', 'shall', 'some', 'same'}
REFLEXIVES = {
    'self', 'myself', 'yourself', 'himself', 'herself', 'itself',
    'ourselves', 'yourselves', 'themselves',
}
TOOL_TAGS = {'<tool_response>': 3.1, '</tool_response>': 1.1,
             '<tool_call>': -.17, '</tool_call>': -.35}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    prev = carry[1] if carry and carry[0] == doc else ''
    state = (doc, raw)
    if raw in TOOL_TAGS:
        return state, TOOL_TAGS[raw]
    if raw == '8':
        return state, .70
    match = re.search(r'[^\W\d_]', raw)
    word = raw[match.start():] if match else ''
    low = word.lower()
    first = low[:1]
    inside = raw[:1].isalpha() and prev[-1:].isalpha()
    value = .01
    if first == 's':
        value += 1.15 - .019 * min(len(word), 12)
        second = low[1:2]
        if second and second in 'aolmnwry':
            value += .36
        elif second and second in 'eiucp':
            value += .11
        elif second == 't':
            value -= .23
        value += .32 * word.startswith('S')
        if inside:
            value -= .24 + .56 * (len(word) <= 3)
            value -= .80 * prev.lower().endswith('s')
        value -= .33 * (low in GRAMMATICAL)
        value -= .58 * (low in ('since', 'several'))
        value -= .75 * (low in ('six', 'seven', 'sixth', 'seventh'))
        value -= .07 * (len(word) > 2 and low.endswith('s'))
        value += .50 * raw.lstrip().startswith('/')
        value += .19 * raw.lstrip().startswith('_')
        if low == 'states' and prev.strip().lower() == 'united':
            value = .02
        if raw == '.S' and prev.rstrip().endswith('U'):
            value = -.13
    elif first and first in 'сسشσς':
        value += 1.20 - .80 * inside
    elif first and first in 'さしすせそサシスセソ':
        value += .85
    elif first and 0xac00 <= ord(first) <= 0xd7a3:
        if (ord(first) - 0xac00) // 588 in (9, 10):
            value += .65  # Korean siot / ssang-siot
    elif inside and prev.lower().endswith('s'):
        value += .45
    if raw in ("'s", '’s'):
        value = -.07
    if raw.strip().lower() in REFLEXIVES:
        value = .85
    if raw.startswith('\t') and len(raw) <= 4 and set(raw[1:]) == {' '}:
        value += .60
    value += 1.10 * (raw.strip() == '###')
    value += .54 * (raw.strip() in ('✓', '√', '§'))
    return state, float(value)

programs.luna:
"""Use s-like starts, the digit 8, and tool-message markers to predict activity.
These surface cues cover several of the component's clearest activation peaks.
"""
import unicodedata

READS = ()

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    lower = token.lower()
    if token == "8":
        return None, 0.70
    if token == "<tool_response>":
        return None, 3.10
    if token == "</tool_response>":
        return None, 1.10
    if token == "<tool_call>":
        return None, -0.17
    if token == "</tool_call>":
        return None, -0.34
    start = lower.lstrip()
    while start and (start[0] in "<>" or unicodedata.category(start[0]).startswith("P")):
        start = start[1:]
    if start.startswith("с"):
        return None, 0.52
    if start.startswith("s"):
        return None, 1.10
    return None, 0.06

programs.sol:
"""Approximate the local casing boundary following capital-letter symbols.

ASCII lowercase singletons and mathematical letter attachments are negative;
digits, dashes, colons and category labels after capitals are positive.
Whitespace, vowels, plural s and the previous token's case/length calibrate
these responses. Other spellings receive a small background activation.
Unicode compatibility spellings (including fullwidth text) are normalized.
The preceding token is remembered, standalone NULs are skipped, and document
changes reset the state. Token-specific background values are not memorized.
"""
import unicodedata

READS = ()
CATEGORY_WORDS = {'type', 'class', 'series', 'format'}


def response(previous, token):
    previous = unicodedata.normalize('NFKC', previous).rstrip('\x00')
    token = unicodedata.normalize('NFKC', token)
    text = token.strip()
    spaced = token[:1].isspace()
    letters = ''.join(c for c in previous if c.isalpha())
    capital_end = bool(previous and previous[-1] in 'ABCDEFGHIJKLMNOPQRSTUVWXYZ')
    upper = capital_end and letters.isascii() and letters.isupper()
    title = bool(letters and any(c.isupper() for c in letters)) and not upper
    size = len(letters)
    value = -0.003

    if len(text) == 1 and text.isascii() and text.islower():
        vowel = text in 'aeiou'
        value = 0.0 if spaced and vowel else 0.02
        if upper:
            if spaced:
                value = -0.8 if size <= 2 else -0.45
            elif text == 's':
                value = -0.56 if size <= 2 else -0.35
            elif vowel:
                value = -0.51 if size == 1 else -0.65
            else:
                value = -0.75 if size == 1 else -0.85
        elif capital_end:
            value = -0.35
        elif title and letters.isascii():
            value = -0.10 if spaced and vowel else -0.05
        elif spaced and previous:
            if previous[-1].isdigit() or previous[-1] in '.-':
                value = -0.11
            elif not previous[-1].isalpha():
                value = -0.035
        elif not spaced and (not previous or previous[-1:] in '([+='):
            value = 0.075
    elif text.isascii() and text.isdigit() and not spaced:
        if upper:
            value = (0.37 if size == 1 else
                     0.43 if size == 2 else 0.31)
            if text == '1':
                value += 0.055
        elif title and size <= 3:
            value = 0.075
    elif upper and text.lower().lstrip('-') in CATEGORY_WORDS:
        value = 0.95 if text.startswith('-') else 0.27
    elif text.startswith('-'):
        if upper:
            suffix = text[1:]
            if spaced:
                value = 0.24
            elif not suffix:
                value = 0.76
            elif len(suffix) == 1 and suffix.islower():
                value = -0.18
            elif suffix[:1].isupper():
                value = 0.4
            else:
                value = 0.1
    elif upper and text in {'‐', '‑', '–', '—'}:
        value = 0.6 if not spaced else 0.2
    elif upper and text == '型':
        value = 0.55  # The Chinese/Japanese word for a type or model.
    elif (upper and text.isascii() and text.islower()
          and text.isalpha()):
        if len(text) <= 3:
            value = -0.055
    elif text in (':', '.', ',', '+'):
        if upper:
            value = {':': 0.33 if size <= 2 else 0.2,
                     '.': 0.15 if previous.startswith('.') else 0.075,
                     ',': -0.045, '+': 0.1}[text]
    elif len(text) == 2 and text[1].isascii() and text[1].islower():
        separator = text[0]
        if separator in '_/([.,)':
            if upper:
                value = -0.66 if separator in '_/.,)' else -0.5
            elif separator == '_':
                value = -0.075 if previous[-1:].isalpha() else -0.2
            elif separator in '/(.':
                value = -0.09 if not previous[-1:].isalpha() else -0.01
    return float(value)


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == document else ''
    token = prefix.token_strings[-1]
    value = response(previous, token)
    remembered = previous if token == '\x00' else token
    return (document, remembered), value

"""A spelling-based detector for express/expression and code's expr.
It also responds to translations, communicating words, and weak lookalikes.
Responses are negative, strongest for express, weaker for expression/expr. A short
suffix recognizes split words, and immediate phrase continuations such as
'expression of' also respond. Everything else is zero; this leaves scattered
background activity unexplained. State resets at document boundaries.
"""
import re

READS = ()
VERBS = {'express', 'expressed', 'expressing', 'expresses'}
NOUNS = {'expression', 'expressions'}
WORD_END = re.compile(r'[a-zа-яё]+$')
RELATED = {
    'convey': -1.45, 'conveyed': -1.4, 'conveys': -1.0,
    'conveying': -0.87, 'stated': -0.46, 'indicated': -0.46,
    'representation': -0.38, 'representations': -0.42,
    'expressly': -1.0, 'expressive': -1.6, 'espresso': -0.8,
    'expres': -2.5, 'pression': -0.6,
}
# Chinese expression-related words/fragments, plus Russian and Korean.
TRANSLATIONS = {
    '表达': -4.45, '表達': -4.45, '表示': -2.1,
    '表': -1.25, '达': -1.65, '達': -1.3,
    '表情': -1.35, '表述': -1.35, '传达': -1.35, '傳達': -1.35,
    '发表': -1.8, '發表': -1.8, '表现': -0.95, '表現': -0.95,
    '表明': -0.5, 'выраж': -2.65, 'выражен': -0.95, '표현': -1.7,
}
CONTINUATIONS = {
    'noun': {'of': -1.75, 'for': -0.2},
    'verb': {'the': -0.5, 'a': -0.5, 'my': -0.5,
             'their': -0.5, 'in': -0.25, 'by': -0.25},
    'chinese': {'式': -1.5, '了': -1.3, '的': -0.55, '方式': -0.55},
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, previous, previous_word = '', '', ''
    else:
        _, tail, previous, previous_word = carry
    token = prefix.token_strings[-1]
    lower = token.lower()
    word = lower.strip().strip('_-.():<>')
    match = WORD_END.search(tail + lower)
    tail = match.group()[-24:] if match else ''
    joined = tail if lower and lower[0].isalpha() else ''
    value, kind = RELATED.get(word, 0.0), ''
    if word in NOUNS or joined in NOUNS:
        value, kind = -2.75, 'noun'
        if word == 'expression' and token.startswith('Expression'):
            value = -3.4
        if previous_word == 'regular':
            value = -1.9
    elif word in VERBS or joined in VERBS:
        value, kind = -3.95, 'verb'
        if word == 'express':
            value = -5.0 if token == 'express' else -4.4
        elif word not in VERBS:
            value = -3.1
    elif word == 'expr':
        value = -2.2 if 'Expr' in token else -1.8
    value = TRANSLATIONS.get(word, value)
    if '表达' in token or '表達' in token:
        value, kind = -4.45, 'chinese'
    elif '表示' in token:
