    " ours": 2.3, " us": 1.6, " We": 1.3, "We": 1.25, " we": 1.3, "we": 0.9,
    " ourselves": 2.1, "ourselves": 2.1,
    " my": 0.9, " My": 0.6, "my": 0.6,
}

# Other languages' short words, matched exactly (lowercased, spaces stripped).
SHORT = {
    "wir": 0.9, "nous": 1.0, "avons": 1.0, "noi": 0.9, "нас": 1.0, "нам": 0.8,
    "мы": 0.6, "nos": 0.6,
}

