STEMS = {
    "我们的": 4.6, "我們的": 4.6, "我们": 2.6, "我們": 2.6, "咱们": 1.7, "우리": 2.4,
    "unser": 3.6, "notre": 3.3, "nostr": 3.4, "nosso": 4.0, "nossa": 4.0,
    "nuestr": 3.0, "наш": 3.4,
