        value = 0.66 if token.startswith(' ') else 0.48
    elif low in {'show', 'shows', 'showing'}:
        value = 0.19
        if previous.strip().lower() in {'the', 'a', 'this', 'that', 'tv', 'talk'}:
            value = 0.52
    elif low in {'act', 'acts', 'acting'}:
        value = 0.27 if token[:1].isspace() else 0.14
        if word[:1].isupper():
            value += 0.20
    elif low in {'co', 'pro', 'micro', 'macro'}:
        value = 0.23
    elif low in {'op', 'mod'}:
        value = 0.22
        if token.startswith('.'):
            value = 0.50
    elif re.fullmatch('match(?:es|ed|ing)?', low):
        value = 0.28 if low == 'match' else 0.21
    elif re.fullmatch('pass(?:es|ed|ing)?', low):
        value = 0.16
        if word.isupper():
            value = 0.32
    elif low in {'maximum', 'maximal', 'maximize'}:
        value = 0.19
    elif re.fullmatch('[A-Za-z]*[xX]', word):
        n = len(word)
