                    value = 0.48 if word == 'X' else 0.45
                    if previous.lower().endswith(('.ts', '.js')):
                        value = 0.78
                elif word == 'x' and previous and (
                    previous[-1].isdigit() or previous.endswith('(')
                ):
                    value = 0.065
        elif low.endswith('ex'):
            value = max(0.0, 0.65 - 0.21 * max(0, n - 3))
