        elif previous.endswith('p') and word in {'seudo', 'seud'}:
            value = -1.8
        elif previous.endswith('approx') and word.startswith('imat'):
            value = -0.9
        elif previous.endswith('virtual') and word in {'ized', 'ization', 'izing'}:
            value = -1.65
        elif previous.endswith('digit') and word in {'ize', 'ized', 'izing', 'ization'}:
            value = -1.45

