    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    start = carry is None or carry[0] != doc
    previous = '' if start else carry[1]
    carry = (doc, token[-1:] if not token.startswith('<|') else '')
    if start and token == '#':
        return carry, -1.09
    if not token:
        return carry, 0.0
    stripped = token.lstrip()
    if stripped != token and stripped[:1].lower() in ('n', 'н'):
        short = len(stripped) == 1
        short = short or (stripped[0].lower() == 'н' and len(stripped) == 2)
        return carry, -0.12 if short else 0.0
    if token[0] == '-' and token[1:2].lower() in ('n', 'н'):
        return carry, -0.48 / (max(1, len(token) - 1) ** 0.25)
    first = token[0].lower()
    length = len(token)
    if first == 'ν':
        return carry, -0.47
    if first == 'ن':
        value = -0.85 / (length ** 0.3)
        if previous in 'نآا' or not previous.isalpha():
            value *= 0.2
        return carry, value
    # Katakana n-syllables, and the hiragana ne syllable.
    if first in 'ナニヌネノンね':
        return carry, -0.55 / (length ** 0.5)
    # Open Korean n-syllables ni and ne.
    if first in '니네':
        return carry, -(1.1 if first == '니' else 0.6) / length
    if first not in 'nн':
        return carry, 0.0
    if not previous.isalpha():
        return carry, -0.13 if previous.isdigit() or previous in '-_:.$' else 0.0
    strength = 1.2 * 0.8 ** max(0, length - 2)
    if length == 1 and first == 'n':
        strength = 1.05
    if length >= 6:
        strength = 0.27
    if token.lower() in CODE_WORDS or token.lower() == 'ness':
        strength = 0.28
    elif length >= 2 and token[0].isupper() and token[1].islower():
        strength *= 0.65 if length == 2 else 0.5
    elif length > 1 and token.isupper():
        strength *= 1.2
    elif first == 'н' and length > 1 and token[1] == 'ы':
        strength = 0.75 * 0.9 ** (length - 2)
    if length == 2 and token.lower()[1] in 'gst':
        strength *= 0.7
    letter = base_letter(previous)
    if letter in 'nн':
        strength *= 0.26
    elif letter in LOW_GAIN_VOWELS:
        strength *= 0.22
    elif letter in MEDIUM_GAIN_VOWELS:
        strength *= 0.72
    elif letter in 'ьъ':
        strength *= 0.57
    elif letter in HIGH_GAIN_CONSONANTS:
        strength *= 1.32
    return carry, -strength

