    'nicht': -1.9, 'kein': -0.55, 'keine': -1.1, 'sans': -0.6,
    'не': -1.65, 'нет': -1.5, 'без': -0.4, 'нельзя': -2.15,
    'ليس': -1.2, 'لا': -0.8, 'không': -1.5, 'tidak': -1.3,
    'niet': -1.0, 'ikke': -1.3, 'ไม': -3.0, 'ไม่': -3.0,
    'unknown': -2.0, 'unclear': -2.6, 'unsure': -3.4,
    'unable': -1.8, 'unnecessary': -2.3, 'unrelated': -2.85,
    'unused': -2.4, 'undefined': -0.65, 'invalid': -0.4,
    'unusual': -0.55, 'impossible': -0.55, 'illegal': -0.5,
    'incorrect': -0.55, 'unlike': -1.3, 'regardless': -0.85,
    '无法': -1.7, '無法': -1.5, '未知': -2.0, '没想到': -3.7,
    '无论': -1.9,
    'ず': -1.5, 'ずに': -1.9, 'らず': -2.6, 'わず': -2.0,
    'なかった': -1.35, '少ない': -0.35, 'かもしれません': -0.1,
