# Frequent grammatical/idiomatic Chinese 不 compounds have distinct strengths.
CHINESE_NOT = {
    # Cannot, will not (simplified/traditional), is not.
    '不能': -2.8, '不会': -3.9, '不會': -4.4, '不是': -3.2,
    '不要': -4.4, '不可': -2.9, '不得': -4.4, '不同': -2.4,
    # Unceasing; not only. The idiom can express a positive statement.
    '不断': -2.0, '不斷': -2.8, '不仅': -3.3, '不僅': -4.2,
    '不过': -3.4, '不過': -3.0, '不少': -3.5, '不错': -3.3,
    '不錯': -3.5, '不足': -3.4, '不管': -4.7, '不敢': -4.8,
    '不可能': -2.7, '不同的': -1.3, '而不是': -1.3, '就不': -1.9,
    '不但': -3.0, '不然': -3.7, '不已': -3.2, '不良': -3.4,
    '不错的': -1.9, '是不是': -0.9, '差不多': -0.9,
}
# English stems with negative affixes; avoid unrelated words like 'inside'.
NEGATIVE_STEMS = (
    'unaccept', 'unaffect', 'unavail', 'unaware', 'unbeli', 'uncert',
    'unchang', 'uncomfort', 'uncon', 'undesir', 'unequal', 'unethic',
    'uneven', 'unexpect', 'unfair', 'unfamiliar', 'unfinished', 'unhappy',
    'unjust', 'unlikely', 'unname', 'unnotic', 'unpublish', 'unread',
    'unreal', 'unreason', 'unresolv', 'unsafe', 'unspecif', 'unstabl',
    'unsuccess', 'unsupport', 'untreat', 'unwant', 'unwill',
    'inade', 'inaccura', 'inactiv', 'incapab', 'incompat', 'incompl',
    'incon', 'ineff', 'ineligi', 'inequal', 'insuff', 'instab', 'invisib',
    'inapprop', 'imperf', 'improp', 'imbalanc', 'irregul', 'irrelev',
    'nonlinear', 'nonzero', 'nonprofit', 'disagree', 'discomfort', 'asymmetr',
)


def activation(token, previous=''):
    w, p = token.strip(), previous.strip().lower()
    s = w.lower()
    spaced = bool(token[:1].isspace())
    if s.endswith('ifndef'):
        return -7.6 if '#' in token else -4.8
    if '!=' in s:
        return -2.9 if spaced else -1.8
    if s.startswith('(!'):
        return -0.75
    if s == '≠':
        return -1.7
    if s.strip('_/') == 'not':
        if w != 'not' or not spaced:
            return -1.0
        if p in ('do', 'does', 'did'):
            return -1.15
        if p in ('is', 'are', 'was', 'were', 'will', 'should', 'may', 'has'):
            return -2.05
        return -1.55
    if s in ("'t", '’t', "n't", 'n’t'):
        if p in ('isn', 'aren', 'wasn', 'weren', 'shouldn'):
            return -2.3
        if p in ('can', 'hasn'):
            return -1.9
        if p in ('won', 'wouldn'):
            return -2.1
        negative_aux = ('don', 'doesn', 'didn', 'couldn', 'haven',
                        'hadn', 'ain', 'n')
        return -1.6 if p in negative_aux else -0.45
    if w.lstrip('.').startswith('isNot'):
        return -2.2
    if w.startswith('Not') and len(w) > 3 and w[3].isupper():
        return -2.2
    if s in NEGATION:
        if s in ('no', 'none') and (w != s or not spaced):
            return 0.0
        if s in ('не', 'нет', 'لا') and not spaced:
            return -0.3
        return NEGATION[s]
    if w in CHINESE_NOT:
        return CHINESE_NOT[w]
    if '不' in w:
        if w == '不':
            return -3.3 if spaced else -4.9
        if w.startswith('不断') and len(w) > 2:
            return -1.1
        if w.startswith('不'):
            return {2: -6.0, 3: -4.5}.get(len(w), -3.5)
        return -3.2
    if w.endswith('ない'):
        return -2.6 if len(w) > 2 else -2.35
    if w.endswith(('なく', 'ません')):
        return -2.1
    if w in ('没', '沒有', '没有', '沒', '未', '勿'):
        return -1.1
    if s.lstrip('_').startswith(NEGATIVE_STEMS):
        return -1.6
    return -0.001


def step(carry, prefix, upstream):
    previous = ''
    if prefix.position and prefix.document_ids[-1] == prefix.document_ids[-2]:
        previous = prefix.token_strings[-2]
    return None, float(activation(prefix.token_strings[-1], previous))

"""A written DO-family detector, not a general action detector.

DO is strongest, its inflections and negative stems weaker. The token's
case and leading space matter. Question/infinitive contexts reduce DO;
subject pronouns increase it. Split negative endings depend on the stem.

There are smaller responses to short do-ending fragments, do-initial
word families, syllables written do in other scripts, and the Chinese
characters 多 (many), 道 (way), and 做 (do). Most other tokens predict zero.
The amplitudes are approximate training averages, not exact token lookups.
"""
READS = ()
QUESTION_WORDS = {'what', 'how', 'why', 'when', 'where'}
SUBJECT_PRONOUNS = {'i', 'you', 'we', 'they', 'he', 'she', 'it'}
NEGATIVE_STEMS = {'don', 'doesn', 'didn'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc
    previous, before = ('', '') if fresh else carry[1:]
    raw = prefix.token_strings[-1]
    word = raw.strip()
    lower = word.lower()
    value = 0.0
    if lower == 'do':
        value = 2.9 if raw.startswith(' ') and word == lower else 3.9
        if fresh:
            value = 4.35 if raw.startswith(' ') else 5.8
        elif previous in {'what', 'how'}:
            value -= 0.6
        elif previous == 'to':
            value -= 1.2 if before in {'what', 'how'} else 0.3
        elif previous in {'who', 'please'}:
            value += 1.1
        elif previous in {'and', 'but', 'that', 'will'}:
            value += 0.45
        elif previous in SUBJECT_PRONOUNS:
            value += 0.2
    elif lower in {'does', 'did'}:
        value = 1.7 if lower == 'does' else 1.4
        if word != lower:
            value -= 0.35
        if previous in QUESTION_WORDS:
            value -= 0.25 if previous == 'why' else 0.6
        elif previous in SUBJECT_PRONOUNS:
            value += 0.2
    elif lower == 'doing':
        value = 1.5
    elif lower == 'done':
        value = 1.0
        if previous in {'have', 'has', 'had'}:
            value += 0.4
    elif lower == 'don':
        value = 0.95 if word == lower else 1.4
    elif lower in {'didn', 'doesn', 'dont', "don't", 'don’t'}:
        value = 0.55
    elif lower in {"'t", '’t', 't'} and previous in NEGATIVE_STEMS:
        value = 0.85 if previous == 'don' else 0.72
    # Similar short syllables and fragments also excite this component.
    elif word in {'ド', 'ど', '도'}:
        value = 1.9
    elif lower == 'до':
        value = 1.1
    elif word == '多':
        value = 1.95
    elif word == '多多':
        value = 2.1
    elif word == '道':
        value = 0.85
    elif word.startswith('做'):
        value = 0.65
    elif lower.lstrip('.-/') == 'do':
        value = 4.7
    elif lower.endswith(('do', 'dos')) and len(lower) <= 5:
        # Short fragments ending in the do syllable, with weaker a/e/i forms.
        value = 0.8 if lower[0] in 'aei' else 1.7
        if raw[:1].isspace():
            value = 0.8
        if lower.endswith('dos'):
            value *= 0.7
    elif lower.lstrip('.-/').startswith('doctr'):
        value = 1.4
    elif lower.lstrip('.-/').startswith('doctor'):
        value = 0.95
    elif lower.lstrip('.-/') in {'doc', 'docs', 'docker'}:
        value = 0.65
        if raw.startswith('/docs'):
            value = 1.65
    elif lower in {'dom', 'domain', 'domains', 'domestic', 'dose', 'dosage'}:
        value = 0.85
    return (doc, lower, previous), value

programs.luna:
"""A sparse written-form cue: strongest on English 'do', with weaker matches
for its inflections, other words containing 'do', and tokens beginning 做.
Keep the current ASCII word so pieces of a split word can be joined.
"""

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        word = ""
    else:
        word = carry[1]

    token = prefix.token_strings[-1]
    for char in token:
        # Treat Han characters as separate words; otherwise a long Chinese
        # sentence would keep its first matching character in carry forever.
        if char.isascii() and char.isalpha():
            word = (word + char.lower())[-64:]
        elif char in "'’":
            if word:
                word = (word + "'")[-64:]
        else:
            word = ""

    # The standalone verb and its common inflections are the strongest cue.
    if word in {"do", "does", "did", "done", "doing", "don't", "doesn't", "didn't"}:
        value = 1.2 if word != "do" else 3.0
    elif "don" in word:
        value = 1.2
    elif "do" in word or token.startswith("做"):
        value = 0.65
    else:
        value = 0.0

    return (doc, word), float(value)

"""A conservative script-based estimate of a rare multilingual signal.

Harvested strong responses often land on short Japanese, Korean, or Thai
syllabic pieces.  Because the cue is weak and context-dependent, this predicts
a small negative amount there and zero for other tokens.
"""
READS = ()


def _script(ch):
    n = ord(ch)
    if 0x3040 <= n <= 0x30FF or 0x31F0 <= n <= 0x31FF:
        return "kana"
    if 0xAC00 <= n <= 0xD7AF:
        return "hangul"
    if 0x0E00 <= n <= 0x0E7F:
        return "thai"
    return "other"


def step(carry, prefix, upstream):
    chars = [c for c in prefix.token_strings[-1].strip() if c.isalpha()]
    if 1 <= len(chars) <= 2 and all(_script(c) != "other" for c in chars):
        return None, -0.28
    return None, 0.0

programs.sol:
"""Recognize attached letter pieces after an e-ending token fragment.

The strongest letter response follows a silent-e-like spelling: an earlier a/i/o/u,
a consonant, then final e. Longer pieces, vowel-vowel endings, and fragments
whose only vowels are e are weaker. Uppercase pieces are attenuated; mixed-case
pieces are weak. Underscores are positive, especially in NAME_ placeholders.
Small corrections cover other continuations, double underscores, hyphens,
digits, and attached 'ed' after non-e letter endings. Everything uses token
spelling and the preceding token, not full-word segmentation or future text.
"""
READS = ()
VOWELS = frozenset('aeiou')


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == document else ''
    token = prefix.token_strings[-1]
    stem = previous.strip().lower()
    earlier_vowels = [c for c in stem[:-1] if c in VOWELS]
    length = len(token)
    e_ending = previous.lower().endswith('e')
    value = 0.0

    if token == '_':
        if previous.strip() == 'NAME':
            value = 1.50
        elif e_ending and earlier_vowels:
            value = 0.79 if previous.endswith('E') else 0.37
        else:
            value = 0.13
    elif token == '__':
        value = -0.04
    elif token.isalpha():
        if e_ending:
            if earlier_vowels:
                if token.islower() or token.isupper():
                    value = (0.0, 0.70, 0.64, 0.50, 0.33, 0.25)[min(length, 5)]
                    if stem[-2] in VOWELS:
                        value *= 0.42
                    elif not any(c in 'aiou' for c in earlier_vowels):
                        value *= 0.54
                    if token.isupper():
                        value *= 0.65
                else:
                    value = 0.06
            elif previous.endswith('e'):
                value = 0.075 if len(stem) <= 2 else 0.13
                if length >= 5:
                    value *= 0.2
        elif token.isascii() and previous[-1:].isalpha():
            if token == 'ed':
                value = -0.075
            elif sum(c in VOWELS for c in stem) >= 2:
                value = 0.08 if length <= 3 else 0.01
    elif e_ending:
        if token == '-':
            if previous.endswith('e'):
                value = 0.18
            elif earlier_vowels:
                value = 0.5
        elif token.startswith('-'):
            value = 0.073
        elif token.isdigit():
            value = 0.042 if previous.endswith('e') else -0.084
        else:
            value = -0.039 if len(previous) <= 3 else -0.01

    return (document, token), float(value)

"""Lexical cues for manipulating or introducing an object.

Training examples show large lexical spikes on Chinese 把 and 将/將,
object-fronting markers, and smaller spikes on related markers, English
put/bring/convert verbs, and type checks. This approximates those cues,
including simple compounds, but deliberately ignores diffuse activity.
"""
READS = ()

RELATIONAL_MARKERS = {
    '对', '對', '対', '以', '按', '按照', '拿', '拿着', '拿著', '连', '連',
    '受到', '深受', '备受', '是以',
}
OBJECT_WORDS = ('我', '你', '他', '她', '它', '自己', '这', '這')
FRAGMENT_STRENGTHS = {
    '把': 8.0, '将': 3.4, '將': 2.4, '被': 1.25, '受': 1.25, '対': 0.7,
}


def response(token):
    word = token.strip().lstrip('._(')
    lower = word.lower()
    if word == '把':
        return 7.45
    if word.endswith('把'):
        return 4.8 if word == '一把' else 6.7
    if word.startswith('把'):
        return 5.7 if word[1:].startswith(OBJECT_WORDS) else 0.6
    if word in ('将', '將', '将其', '將其'):
        return 3.6
    if word.endswith(('将', '將')) and word != '麻将':
        return 1.4 if word.startswith(('即', '必', '预计')) else 3.6
    if word.startswith(('将', '將')):
        return 0.75 if word.endswith(('会', '會', '来', '來')) else 1.3
    if word == '被' or word.endswith('被') or word in ('受', '不受'):
        return 1.1
    if word in RELATIONAL_MARKERS:
        return 0.8
    if lower in ('put', 'putting', 'puts'):
        if word == 'PUT':
            return 0.46
        if lower == 'puts':
            return 1.03
        return 0.85 if token[:1].isspace() or word[:1].isupper() else 0.65
    if lower in ('bring', 'brings', 'bringing', 'brought'):
        return 0.68 if lower == 'brought' else 0.8
    if lower in (
        'convert', 'converts', 'converting', 'converted', 'verting'
    ):
        return 0.42 if lower == 'converted' else 0.65
    if lower in ('isinstance', 'assertisinstance'):
        return 1.05
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if '\ufffd' in token:
        # Recognize a marker completed by a UTF-8 fragment.
        if prefix.position and (
            prefix.document_ids[-1] != prefix.document_ids[-2]
        ):
            return None, 0.0
        token = prefix.text_prefixes[-1][-1:]
        return None, FRAGMENT_STRENGTHS.get(token, response(token))
    return None, response(token)

programs.haiku:
"""Layer-0 MLP down-projection component 3092 of Qwen3-1.7B.

What it does: it reads the word that introduces the *object of a handling verb*,
i.e. the word after which the thing being moved, taken, changed or transferred
is about to be named. The strongest case is the Chinese disposal marker 把
("take/handle X": 我把, 要把, 把它 ...), then the formal future/disposal marker
将/將 ("will; will ... X"), then the passive/affected markers 被/受/遭, then
coverbs and verbs of taking, handling or transforming (以, 对/對, 按/按照,
连/連, 拿, and English put / bring / convert in every inflection).

The activation depends almost only on the current token (it is near 0 on
ordinary words), so the program looks only at the newest token and returns a
fixed level per concept. Levels are the mean activations measured on training text.
"""

READS = ()

PUT_VERBS = {
    "put", "puts", "putting", "bring", "brings", "brought", "bringing",
    "convert", "converts", "converted", "converting",
}
# Standalone words (exact match, so 可以 or 所以 do not count).
COVERBS = {"以": 0.9, "对": 0.75, "對": 0.75, "按": 0.8, "按照": 0.75,
           "连": 0.8, "連": 0.7, "拿": 0.75, "捧": 0.7, "受": 1.0, "被": 1.2}


def level(token: str) -> float:
    word = token.strip().lower().lstrip(".")
    if "把" in token and not any(c in token for c in "握持"):
        return 6.4  # disposal marker 把: "take / handle X"
    if any(c in token for c in "将將"):
        return 3.3  # 将/將: "will ... X", the formal disposal marker
    if any(c in token for c in "被受遭"):
        return 1.0  # passive / affected markers
    if token.strip() in COVERBS:
        return COVERBS[token.strip()]
    if word in PUT_VERBS:
        return 0.76  # put / bring / convert verbs
    return 0.0


def step(carry, prefix, upstream):
    # Each position depends only on its own token, so no state is carried.
    return carry, float(level(prefix.token_strings[-1]))

programs.sol:
"""A lexical space detector, with weaker cues for places and emptiness.

Strong responses mark spellings of 'space', workspace/namespace, and Chinese
or Japanese words for space. Selected rooms, gaps, and spatial word families
are weaker cues. Case, plurality, and token-leading separators change strength.
Detached spelling fragments are included; 'sp' + 'ace(s)' is joined only
within the same document. All other tokens get zero. This approximates the
main lexical responses, not the smaller token-specific or contextual effects.
"""

READS = ()

ROOMS = {'room', 'rooms', 'classroom', 'classrooms', 'workplace'}
PLACES = {'home', 'homes', 'palace', 'environment', 'environments',
          'territory', 'marketplace', 'cavity', 'hole', 'holes', 'universe',
          'bedroom', 'bathroom', 'restroom', 'chamber', 'compartment',
          'hallway', 'apartment', 'apartments', 'residence'}
EMPTINESS = {'empty', 'blank', 'emptiness'}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    text = token.strip()
    word = text.lstrip('./_-').lower()
    leading_space = token[:1].isspace()

    if word in {'space', 'spaces'}:
        value = 4.0 if word == 'spaces' else 5.1
        if leading_space and word == 'space':
            value = 4.7
        if text[:1].isupper():
            if word == 'spaces':
                value = 4.5 if leading_space else 5.9
            elif leading_space or text.isupper():
                value = 5.4
        if text.startswith('-'):
            value = 6.0
        elif text.startswith('_'):
            value = 4.7
    elif word in {'workspace', 'workspaces'}:
        value = 3.7 if text[:1] in './' else 4.2
    elif word in {'namespace', 'namespaces'}:
        value = 5.3 if leading_space else 6.0
        if text[:1].isupper() or text[:1] in './_':
            value = 4.2
        if word.endswith('s'):
            value -= 0.7
    elif word in {'whitespace', 'itespace', 'ospace'}:
        value = 2.8
    elif word in {'pace', 'paces', 'paced'}:
        value = 1.0 if leading_space or text.startswith('-') else 3.9
        if word == 'paces' and not leading_space:
            value = 4.8
        elif word == 'paced' and not leading_space:
            value = 2.6
    elif word in {'空间', '空間', '的空间', 'スペース'}:
        value = 4.3
    elif word in {'空', '间', '間', '客厅', '間に', '一间', '房间', '房間'}:
        value = 1.2
    elif word in {'室', '厅', '实验室', '办公室', '教室', '洞', '穴', '孔',
                  '之间', '之間', '宇宙', '天空'}:
        value = 0.8
    elif word in {'espacio', 'espaço', 'acios'}:
        value = 2.7
    elif word in {'spatial', 'patial', 'spacious'}:
        value = 1.6
    elif word in {'landscape', 'landscapes', 'andbox', 'sandbox'}:
        value = 1.2
    elif word in ROOMS:
        value = 1.0
    elif word in PLACES or word in EMPTINESS or word in {'ace', 'aces', 'escape'}:
        value = 0.7
    elif word in {'spacing', 'spaced', 'spac', 'spacer'}:
        value = 0.75
    elif word in {'spaceship', 'spacecraft', 'aerospace'}:
        value = 1.3
    elif word in {'package', 'packages'}:
        value = 0.45 if leading_space else 1.0
    else:
        value = 0.0
    # Recognize a split spelling: 'sp' followed by 'ace' or 'aces'.
    if word in {'ace', 'aces'} and prefix.position > 0:
        if prefix.document_ids[-2] == prefix.document_ids[-1]:
            previous = prefix.token_strings[-2].lower()
            if previous.endswith('sp'):
                value = 5.0 if word == 'ace' else 4.0
    return None, value

programs.haiku:
"""The component reads the idea of "space". It is strongest on the English words
"space" and "namespace" (and compounds like workspace), weaker on the same idea in other
languages, and weaker still on nouns for rooms, homes and places. Everything else is about 0."""
READS = ()

NAMESPACE = {"namespace", "namespaces"}
SPACE_WORDS = {"space", "spaces", "workspace", "whitespace", "pace"}
SPACE_PARTS = ("space", "spac", "spatial")
OTHER_LANGUAGE = {"空间", "空間", "間", "间", "时空", "espaço", "espacio", "spazio", "espace",
                  "raum", "zimmer", "platz", "室", "空", "スペース"}
PLACE_WORDS = {"room", "rooms", "home", "homes", "environment", "environments", "hole",
               "holes", "chamber", "apartment", "apartments", "classroom", "restroom",
               "bathroom", "bedroom", "territory", "escape", "landscape", "realm", "empty"}

def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    word = tok.strip().strip("/.-_\t").lower()
    if "namespace" in word:
        return None, 5.2
    if word in SPACE_WORDS:
        return None, 4.2
    if word in OTHER_LANGUAGE or tok.strip() in OTHER_LANGUAGE:
        return None, 1.6
    if any(part in word for part in SPACE_PARTS):
        return None, 1.35
    if word in PLACE_WORDS:
        return None, 0.75
    return None, 0.0

programs.luna:
"""Respond to lexical cues for space and familiar places.

The strongest cue is the written family of “space” (including compound words
and its Chinese forms). “Pace” can arrive as a split token, so it has a
smaller value; room and home words provide weaker place-related cues.
"""

READS = ()


