    doc = prefix.document_ids[-1]
    reset = carry is None or carry[0] != doc
    previous, fragment = ('', '') if reset else carry[1:]
    token = prefix.token_strings[-1]
    raw = token.strip()
    word = raw.lstrip('._/[(-').lower()
    spaced = token[:1].isspace()
    joined = (fragment + raw).lower() if not spaced and raw.isalpha() else word
    if joined in POSITIONS or joined in {'digit', 'digits', 'bit', 'bits'}:
        word = joined
