    if '位' in raw:
        if raw == '位':
            value = 7.5 if previous.endswith('上') else 6.25
            if previous[-1:].isdigit():
                value = 5.8
            elif previous.endswith(('順', '顺')):
                value = 4.1
        elif raw in {'各位', '每一位'}:
            value = 6.5
        elif (len(raw) == 2 and raw[0] in COUNTS) or raw in {'高位', '低位'}:
            value = 5.0
        elif raw in {'这位', '這位', '那位'}:
            value = 4.5
        elif raw.endswith('一位') or raw.startswith('第'):
            value = 4.2
        elif raw == '到位':
            value = 4.0
        elif raw in {'定位', '地位', '方位', '首位'}:
            value = 3.0
        elif raw in {'单位', '單位', '全方位'}:
            value = 1.45
        elif raw in {'部位', '品位', '仓位', '床位', '停车位'}:
            value = 1.0
        elif raw == '穴位' or raw.endswith('单位'):
            value = 0.4
        else:
            value = 2.2 if len(raw) == 2 else 1.6
    elif raw in {'위', '위치', 'vị'}:
        value = 2.4 if spaced and raw == '위' else 3.0
    elif raw in {'座', '一座', '这座'}:
        value = 1.15 if len(raw) == 1 else 0.65
    elif raw in {'くらい', 'ぐらい', 'どちら'}:
        value = 0.95
    elif word in POSITIONS:
        value = 1.8 if spaced and word == 'position' else 1.55
        if not spaced:
            value = 1.7 if raw[:1].isupper() else 1.3
            if raw.isupper():
                value = 0.4
            elif fragment.lower().endswith(('decom', 'com', 'pro', 'dis', 'ex')):
                value = 0.3
            elif fragment.lower().endswith(('super', 'sup', 'im', 'pre')):
                value = 0.65
    elif word == 'positional':
        value = 1.1
    elif word in {'located', 'locate', 'locating', 'situated', 'situ'}:
        value = 1.28 if word == 'located' else 1.0
        if not spaced:
            value *= 0.8 if raw[:1].isupper() else 0.6
    elif word in {'location', 'locations'} or word in COORDINATES:
        value = 0.72
    elif word in {'digit', 'digits'}:
        value = 1.0 if word == 'digit' else 0.8
    elif word in {'bit', 'bits'}:
        value = 0.9 if word == 'bit' and spaced else 0.73
        if not spaced and raw.isalpha() and (raw.islower() or raw.isupper()):
            value = 0.45
    elif word == 'another':
        value = 0.46 if previous == 'one' else 0.72
    elif word in {'seat', 'seats', 'seating', 'seated'}:
        value = 1.15 if word == 'seat' and spaced else 0.75
    elif word in {'pos', 'loc', 'coord', 'coords'}:
        value = 0.4
    elif spaced and word in PLACE_TRANSLATIONS:
        value = 0.8
    elif word == 'of':
