"""Short ni-like spelling fragments, rather than every word containing 'ni'.

Bare ni syllables are strongest. Appending letters usually weakens the signal,
with different strengths for vowel prefixes and writing systems. Hiragana に
is weaker than katakana ニ. Longer words normally get zero. Byte-split ni
characters are recognized when the current token completes the character.
A few neighboring n spellings have smaller responses. The rule approximates
lexical responses; it does not model contextual variation.
"""
import re

READS = ()
NI = {'ni': 3.1, 'ani': 3.5, 'ini': 3.1, 'oni': 2.15,
      'uni': 2.1, 'eni': 2.0, 'ニ': 4.2, '尼': 4.4, '妮': 2.8,
      '니': 3.2, 'に': 0.98, 'ني': 2.2, 'ни': 2.45, 'ня': 1.5,
      'اني': 1.5, 'نية': 2.4}

CONSONANTS = 'bcdfghjklmnpqrstvwxyz'


def spelling(raw):
    s = raw.strip().lower().lstrip('._-(')
    if s in NI:
        value = NI[s]
        if s in ('ani', 'ini') and raw != raw.lstrip(' ._-('):
            value *= 0.72
        return value
    # Latin ni, with an optional vowel before it and a short ending.
    m = re.fullmatch('([aeiou]?)ni([a-z]{1,2})', s)
    if m:
        vowel, ending = m.groups()
        base = NI[vowel + 'ni']
        if not vowel:
            if ending in ('te', 'si', 'ke', 'ck'):
                if ending == 'ck' and raw.strip()[:1].isupper():
                    return 0.3
                return 2.0 if ending in ('te', 'si') else 1.3
            if len(ending) == 2:
                return 0.15
            return {'l': 1.75, 'n': 0.25, 't': 1.0,
                    'a': 2.0, 'o': 1.65, 'e': 1.25}.get(ending, 1.35)
        if vowel == 'u' and ending not in ('a', 'c', 'k', 'x'):
            return 0.0
        scale = {'n': 0.2, 'ng': 0.05, 't': 0.2, 'a': 0.6,
                 'o': 0.6, 'e': 0.4}.get(ending, 0.45 ** len(ending))
        return base * scale
    if s in ('anni', 'mini', 'dni'):
        return 0.5 if s == 'anni' and raw.startswith(' ') else 1.6
    if re.fullmatch(f'[{CONSONANTS}]ani', s):
        return 2.4
    if re.fullmatch(f'[{CONSONANTS}]ania', s):
        return 2.1
    if re.fullmatch(f'[{CONSONANTS}][aeiou]ni[ace]', s):
        return 0.8
    if s in ('ney', 'ony', 'ny', 'ní', 'ını', 'ń', 'ň'):
        return {'ney': 1.3, 'ony': 0.85, 'ny': 0.4, 'ní': 1.5,
                'ını': 0.75, 'ń': 0.8, 'ň': 1.2}[s]
    # Cyrillic fragments: exclude the common pronouns oni and nikh.
    if s not in ('они', 'них') and re.fullmatch('[аеоу]?ни[а-я]{0,3}', s):
        if len(s) == 3 and s.endswith('ни'):
            return 1.5
        if s.startswith('ени'):
            return 0.15 if s.endswith('е') else 0.3
        if s.startswith('ни') and len(s) == 3:
            return {'ч': 1.7, 'й': 0.4, 'е': 0.4}.get(s[-1], 1.0)
        return 2.45 * 0.6 ** (len(s) - 2)
    if s in ('ней', 'нее', 'ень', 'な', 'ナ', 'น'):
        return 0.85 if s in ('ней', 'нее') else 0.3
    if 'ニ' in s and len(s) <= 3:
        return 4.2 * 0.5 ** (len(s) - 1)
    if s.startswith('尼') and len(s) <= 4:
        return 4.4 * 0.6 ** (len(s) - 1)
    return 0.0


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    # Decode a completed character only for byte-fragment tokens.
    if '\ufffd' in raw and len(prefix.document_ids) > 1:
        if prefix.document_ids[-1] == prefix.document_ids[-2]:
            completed = prefix.text_prefixes[-1][-1:]
            if completed in ('ニ', '尼', '妮', '니'):
                return None, float(spelling(completed) * 0.9)
    return None, float(spelling(raw))

