BARE_NI = frozenset(["ni", "ní", "ни", "ня", "ني"])
LATIN_NI = re.compile(r"[aeiouy]{0,2}n[ií][a-z]{0,2}|[a-z]?ni[a-z]{0,2}")
CYRILLIC_NI = re.compile(r"[а-яё]{0,2}н[иья][а-яё]{0,2}")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().lower()
    if token in KANA_HANJA_NI:
        value = 4.0
    elif token == "に":
        value = 1.0
    elif token in BARE_NI:
        value = 2.5
    elif LATIN_NI.fullmatch(token) and len(token) <= 3:
        value = 2.0
    elif LATIN_NI.fullmatch(token) and len(token) == 4:
        value = 0.6
    elif CYRILLIC_NI.fullmatch(token) and len(token) <= 3:
        value = 0.8
    else:
        value = 0.0
    return carry, value

