MODALS = {
    'would': (-5.45, -1.15, -1.90, -0.95, -0.55),
    'could': (-1.27, 0.08, -0.27, -0.28, 0.03),
    'might': (-1.27, 0.13, -0.13, -0.16, 0.04),
    'should': (-0.76, 0.15, 0.27, -0.10, 0.02),
}
OTHER_AUXILIARIES = {
    'würde': -2.5, 'wür': -2.5, 'wäre': -2.5,
    'hätte': -1.3, 'hät': -1.88, 'serait': -2.05,
    'sería': -1.92, 'zou': -2.13, 'skulle': -1.90,
    'shall': -0.28, 'ought': -0.28, 'will': 0.06, 'can': -0.04,
}
