NEGATIVE_STEMS = {'wouldn': -3.2, 'couldn': -0.70, 'shouldn': -0.50}
NEGATION_ENDINGS = {
    'wouldn': -5.0, 'couldn': -0.94, 'shouldn': -0.57,
    'won': -0.78, 'can': -0.18, 'hadn': -0.51,
}
AFTER_WOULD = {
    'be': 0.25, 'have': 0.14, 'not': 0.28,
    'you': 0.43, 'it': 0.21, 'i': 0.23, 'we': 0.23, 'this': 0.20,
}


def subject_group(word):
    if word in {'i', 'we'}:
        return 1
    if word == 'you':
        return 2
    if word in {'it', 'this', 'which', 'what'}:
        return 3
    if word in {'he', 'she', 'they', 'that', 'who'}:
        return 4
    return 0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, last_value, strength, age = '', 0.0, 0.0, 4
    else:
        _, previous, last_value, strength, age = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    group = subject_group(previous)
    age += 1
    value = OTHER_AUXILIARIES.get(word, 0.0)

    if word in MODALS:
        weights = MODALS[word]
        value = weights[0] + (weights[group] if group else 0.0)
        if word == 'would':
            if previous in {'why', 'anyone'}:
                value -= 1.45
            if not token.startswith(' '):
                value += 0.30
