        value = NEGATIVE_STEMS[word]
    elif token in ("'d", '’d'):
        value = (-2.0, -3.65, -4.68, -3.0, -3.25)[group]
    elif token in ("'t", '’t'):
        value = NEGATION_ENDINGS.get(previous, 0.0)
        if previous == 'wouldn' and token == '’t':
            value += 0.35
    elif token in ("n't", 'n’t'):
        value = {'would': -3.1, 'could': -0.65, 'should': -0.5}.get(previous, 0.0)
    elif token in ("'ll", '’ll'):
        value = -0.48
    elif token == ' бы':  # A standalone Russian conditional particle.
        value = -1.16
    elif token in ('会', '會'):
        value = -1.07 if token == '会' else -1.37
    else:
        chinese = token.replace('會', '会')
        if chinese in {'我会', '你会', '他会', '她会'}:
            value = -1.3
        elif chinese in {'不会', '都会', '就会', '也会', '可能会',
                         '一定会', '就不会', '会有', '会导致'}:
            value = -0.78
        elif chinese in {'还会', '将会', '会出现', '会影响'}:
            value = -0.5

    if previous == 'would':
        value += last_value * AFTER_WOULD.get(word, 0.0)
    elif previous in ("'d", '’d'):
        value += last_value * {'be': 0.65, 'have': 0.27}.get(word, 0.0)
    elif age in (2, 3):
        fraction = {'be': 0.25, 'have': 0.15, 'been': 0.20}.get(word, 0.0)
        value += strength * fraction * 0.55 ** (age - 1)

    if word == 'would' or token in ("'d", '’d'):
        strength, age = value * (1.0 if word == 'would' else 1.5), 0
