def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    line_has_text = carry[1] if carry and carry[0] == doc else False
    token = prefix.token_strings[-1]
    text = token.strip()
    value = 0.0

    if '@' in token:
        before, after = token.split('@', 1)
        if '\n' in token:
            value = 0.9 if '@@' in token else 3.7
        elif text == '@':
            value = 7.0 if token.startswith(' ') else 7.2
        elif text == '@@':
            value = 2.6 if token.startswith(' ') else 4.8
        elif after.startswith('/'):
            value = 2.5  # Module-import aliases such as '@/...'.
        elif after.startswith('['):
            value = 3.4
        elif after.isalpha():
            value = 5.6 if len(after) == 1 else 3.2
        elif after:
            if text.startswith(':@"'):
                value = 1.0  # Objective-C string-literal introducer.
            elif '"' in before and '"' in after:
                value = 5.0
            else:
                value = 4.5 if '(' in after else 2.7
        elif '[' in before:
            value = 4.3  # Citation introducer [@.
        elif ',' in before:
            value = 4.7
        elif '/' in before:
            value = 5.9 if '//' in before else 7.6
        elif '{' in before:
            value = 2.5 if "'" in before else 5.1
        elif text == '(@':
            value = 6.2 if token.startswith(' ') else 5.3
        elif "'" in before:
            value = 7.8
        else:
            value = 6.6
    elif '＠' in token:
        value = 3.7
    elif '#' in token:
        inline = line_has_text or bool(token.split('#', 1)[0].strip())
        if text.startswith('#['):
            value = 0.93  # Rust-style attributes.
        elif text.startswith('#define'):
            value = 0.51
        elif text.startswith('###'):
            value = 0.62
        elif '&' in token:
            value = 0.2  # HTML numeric entities.
        elif inline:
            value = 0.5
        else:
            value = 0.2 if text == '##' else 0.03
    elif '©' in token or '®' in token:
        value = 1.4
    elif text.startswith('/**'):
        value = 0.62

    if '\n' in token:
        line_has_text = bool(token.rsplit('\n', 1)[-1].strip())
    else:
        line_has_text = line_has_text or bool(token.strip())
    return (doc, line_has_text), value

