"""A spelling detector for b-bearing syllables, strongest on short -ub forms.

Longer b-containing words receive weaker responses. Several semantic relatives
of common b-words (web/internet, cube/square, tube/pipe, lb/pound) also respond.
A small one-token continuation signal is reset at document boundaries.
Fixed gains approximate training averages; this does not explain every token.
"""
from functools import lru_cache

READS = ()

# Latin prefixes and stems whose b lies inside a longer token.
STEMS = {
    'public': 1.5, 'publish': 1.2, 'publisher': 2.4,
    'subscrib': 2.7, 'substitut': 1.8, 'subject': 0.65,
    'submit': 0.55, 'subset': 0.5, 'subsequen': 0.4,
    'subtract': 0.6, 'substant': 1.1,
    'github': 0.7, 'ithub': 0.7,
}
# Semantic associates of frequent b-containing forms.
ASSOCIATES = {
    'internet': 0.8, 'online': 0.7, 'social': 0.75,
    'square': 0.8, 'pipe': 0.8, 'pound': 0.7,
}
FUNCTION_WORDS = {'be', 'been', 'being', 'by', 'but', 'about', 'because',
                  'before', 'between', 'both'}


STEM_RULES = sorted(STEMS.items(), key=lambda rule: len(rule[0]), reverse=True)


@lru_cache(maxsize=8192)
def spelling(text):
    s = text.strip().lstrip('./(_-').lower()
    if s in FUNCTION_WORDS:
