    r'(?:travel|(?:re)?model|cancel|label|signal|counsel|marvel|fuel|quarrel|'
    r'dial|jewel|worship)(?:ed|ing|er|ers)'
)
OTHER_US = re.compile(
    r'(?:aluminum|maneuver|catalog|analog|artifact|pediatric|sulfur|leukemia|'
    r'anemia|encyclopedia|airplane|plow|mold|cozy)(?:s|ed|ing|al|er|ers|ic)?'
)
SUFFIX_LEVEL = {'ize': 3.75, 'ized': 3.6, 'izing': 3.4}


def english(word, leading_space):
    def whole_word(value):
        # These cues are weaker inside an identifier or a word fragment.
        return value if leading_space else 0.8 * value

    if word == 'maize' or NOT_IZE.fullmatch(word):
        return 0.004
    match = IZE.fullmatch(word)
    if match:
        if word == match[1]:
            return SUFFIX_LEVEL.get(word, 3.0)
        return whole_word(2.7)
    if re.fullmatch(r'favorites?|favoritism|colorful|behavioral', word):
        return 3.7
    if AMERICAN_OR.fullmatch(word) or re.fullmatch(r'gray(?:s|ed|ing|ish)?', word):
        return whole_word(2.5)
    if re.fullmatch(r'(?:center|fiber)(?:s|ed|ing|piece|pieces)?', word):
        return whole_word(2.5)
    if re.fullmatch(r'theater(?:s|ical)?', word):
        return 3.6
    if re.fullmatch(r'(?:kilo|centi|milli|micro|nano)meters?', word):
        return 1.7
    if word == 'liters':
        return 1.9
    if word in {'meter', 'meters', 'liter'}:
        return 0.9
    if re.fullmatch(r'(?:defen|offen)se(?:s|less|lessly)?', word):
        return 3.0
    if re.fullmatch(r'[a-z]*alyz(?:e[ds]?|ing|ers?)', word):
        return 2.2
    if word in {'license', 'licenses'}:
        return 1.5
    if word in {'licensed', 'licensing'}:
        return 0.6
    if SINGLE_L.fullmatch(word) or word in {'enrollment', 'fulfill', 'fulfillment'}:
        return 2.2
    if word == 'jewelry':
        return 3.8
    if OTHER_US.fullmatch(word):
        return whole_word(1.6)
    if word in {'program', 'programs', 'toward', 'afterward', 'backward',
                'judgment', 'judgments', 'mom', 'moms'}:
        return whole_word(1.0)
    if word in {'percent', 'lineup', 'tire', 'tires', 'sulfate'}:
        return 1.5
    if word == 'iz':
        return 0.25 if leading_space else 0.9
    if word in {'avor', 'umor', 'avored'}:
        return 1.9
    if BRITISH_OR.fullmatch(word) or BRITISH_ISE.fullmatch(word):
        return 0.9
    if word in {'ised', 'isation', 'isations'}:
        return 0.7
    return None


def other_notation(token, word):
    # Russian words where е is often used instead of ё, plus their fragments.
    if token[:1].isspace():
        if word in {'ее', 'еще', 'свое'} or word.startswith(('ребен', 'объем')):
            return 3.3
        if word.startswith(('учет', 'счет', 'расчет')) or word == 'своем':
            return 2.4
        if word == 'все':
            return 1.5
    elif word in {'ъем', 'чет', 'дет'}:
        return 2.4
    if word in {'ет', 'ем', 'ется', 'ез', 'ё', 'ёт', 'ён', 'ёр', 'ём',
                'ещё', 'её', 'всё', 'своё'}:
        return 0.7
    # Hiragana rather than kanji writing of common Japanese words.
    if 'こと' in word:
        return 1.35
    if word.startswith('とき'):
        return 2.0
    if word in {'ほか', 'すべて'}:
        return 2.8
    if word in {'いい', 'いろいろ'} or word.startswith(('わか', 'さまざま')):
        return 1.65
    if word.startswith('でき'):
        return 0.85
    # Thai repetition mark, German sharp s, and cedilla letter forms.
    if word == 'ๆ':
        return 1.4 if token[:1].isspace() else 4.0
    if word == 'ß':
        return 0.75
    if word == 'daß':
        return 1.4
    if word == 'ş':
        return 1.35
    if word == 'ţ':
        return 2.1
    # Two simplified Chinese character variants.
    if word in {'儿', '着'}:
        return 1.65
    # Arabic words containing alif with hamza.
    if token[:1].isspace() and ('أ' in word or 'إ' in word):
        return 1.15
    if token.strip() in {':=', 'NULL'}:
        return 1.3
    if token == '<think>':
        return 0.9
    if token == '</think>':
        return 0.33
    return 0.004


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lstrip('._-/(:=').lower()
    value = english(word, token[:1].isspace())
    if value is None:
        value = other_notation(token, word)
    elif token.strip()[:1].isascii() and token.strip()[:1].isupper():
        value *= 0.85
    return None, float(value)

"""A lexical play / games / performance signal, with a short local echo.

Play and its grammatical forms are strongly negative; players, compounds,
and a small multilingual play vocabulary are weaker. The spelling-neighbour
pay also responds. After a form of play, articles and some prepositions retain
part of its signal. Otherwise the prediction is zero. Documents reset the echo.
"""

READS = ()
PLAY = {'play': -6.6, 'plays': -6.85, 'played': -5.4, 'playing': -5.7}
DERIVED = {
    'player': -1.25, 'players': -1.3, 'playable': -3.9,
    'playful': -1.75, 'playoff': -1.65, 'playoffs': -1.5,
    'gameplay': -2.35, 'playground': -2.4, 'playwright': -2.45,
    'playback': -2.4, 'replay': -2.9, 'playlist': -1.9,
    'playbook': -2.15, 'playstation': -1.2, 'pygame': -1.15,
    'multiplayer': -0.75, 'screenplay': -1.0,
}
PERFORM = set('播放 发挥 扮演 演奏 奏 プレイ'.split())
PLAY_TRANSLATIONS = set('spiel spielen jouer играть chơi 戏 戲 玩耍'.split())
GAMES = set('jeu jeux juego juegos jogo игры игров игрок'.split())
CHINESE_PLAY = set('玩 游 遊 玩家 游戏 遊戲 演 打 唱'.split())
ENTERTAINMENT = set('comedy drama orchestra picnic plot plots'.split())
PAY = set('pay pays paying payroll'.split())
ECHO = {'a': 0.28, 'an': 0.25, 'the': 0.10,
        'for': 0.045, 'in': 0.02, 'on': 0.02}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, strength = ('', 0.0)
    if carry is not None and carry[0] == doc:
        previous, strength = carry[1:]
    token = prefix.token_strings[-1]
    raw = token.strip()
    word = raw.lstrip('.-_/([').lower()
    value = PLAY.get(word, DERIVED.get(word, 0.0))
    if word == 'playing' and (raw[:1].isupper() or not token[:1].isspace()):
        value = -5.0
    for vocabulary, response in (
        (PERFORM, -2.65), (PLAY_TRANSLATIONS, -1.8), (GAMES, -0.8),
        (CHINESE_PLAY, -1.05), (ENTERTAINMENT, -0.65), (PAY, -0.95),
    ):
        if word in vocabulary:
            value = response
    if word in {'game', 'games', 'gamer', 'gamers'}:
        value = -0.55 if word != 'games' else -0.43
    elif word == 'paid':
        value = -0.4
    elif word in {'иг', 'игр'} and token[:1].isspace():
        value = -1.95 if word == 'иг' else -1.05
    if previous in PLAY:
        value += strength * ECHO.get(word, 0.0)
        if word == 'of' and previous == 'play':
            value += 0.35 * strength
        elif word == 'ground':
            value -= 0.85
    elif previous == 'иг' and strength < -1 and word == 'ра':
        value -= 1.1
    return (doc, word, value), float(value)

programs.luna:
"""Estimate the negative response to words about games, play, and pastimes."""
import unicodedata

READS = ()

GAME_WORDS = frozenset({
    "game", "games", "gaming", "gamer", "gamers", "gameplay",
    "spiel", "spiele", "spielen", "spieler", "juego", "juegos", "jugar",
    "jouer", "joué", "jeux", "игра", "игре", "игру", "игр", "играют",
    "иг", "ра", "게임", "ゲーム", "遊び", "遊ぶ", "玩", "玩耍",
    "游戏", "遊戲", "打",
})
PASTIME_WORDS = frozenset({
    "comedy", "orchestra", "picnic", "plot", "pause", "pay", "pays",
    "paying", "payroll", "pytest",
})


def step(carry, prefix, upstream):
    word = unicodedata.normalize("NFKC", prefix.token_strings[-1]).casefold().strip()
    letters = "".join(ch for ch in word if ch.isalpha())
    previous = ""
    if len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        previous = "".join(ch for ch in unicodedata.normalize(
            "NFKC", prefix.token_strings[-2]).casefold() if ch.isalpha())

    if letters in {"play", "played", "plays", "playing"}:
        return None, -6.0
    if letters.startswith("play"):
        return None, -1.5
    if letters in GAME_WORDS or "game" in letters:
        if letters in {"ра", "рают"} and not previous.startswith("иг"):
            return None, 0.0
        return None, -0.8
    if letters in PASTIME_WORDS:
        return None, -0.7
    # A frequent continuation after an English play/played token is "a".
    if letters == "a" and previous in {"play", "played", "plays", "playing"}:
        return None, -1.5
    return None, 0.0

programs.sol:
"""Sparse lexical and formatting biases; not a unified semantic detector.

Thinking tags are positive, while message/tool-call markers tend negative.
ViewChild (an Angular query) is strongly positive and 五官 ('facial features')
strongly negative. Leading space weakens the ViewChild response. Digits, selected
layout characters, and directory names have smaller biases. Everything else
gets a near-zero baseline; fine-grained word and contextual effects are omitted.
"""
READS = ()

MARKERS = {
    '<think>': 0.170, '</think>': 0.145,
    '<|im_start|>': -0.051, '<|im_end|>': -0.015,
    '<|endoftext|>': 0.008,
    '<tool_call>': -0.077, '</tool_call>': -0.041,
    '<tool_response>': 0.043,
}

# Responses for ASCII digits, ordered 0 through 9.
DIGITS = (
    0.0037, 0.0011, 0.0031, 0.0035, 0.0083,
    0.0031, -0.0039, 0.0047, -0.0111, 0.0042,
)


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    w = s.strip()
    value = -0.0006
    if s in MARKERS:
        value = MARKERS[s]
    elif w == 'ViewChild':
        value = 0.467 if s.startswith(' ') else 0.758
    elif w == '五官':
        value = -0.660
    elif len(s) == 1 and '0' <= s <= '9':
        value = DIGITS[int(s)]
    elif s == '\u00a0':  # Nonbreaking space.
        value = 0.031
    elif w == '\\t':  # Written-out tab escape, not an actual tab.
        value = -0.042
    elif w == '__':
        value = -0.024
    elif w == '?':
        value = -0.018
    elif w == '$':
        value = 0.024 if s.startswith(' ') else 0.010
    elif w == '/workspace':
        value = -0.107
    elif w == 'workspace':
        value = -0.041
    elif w == '/src':
        value = 0.055
    return None, float(value)

programs.haiku:
"""Candidate 1: document-start effect + a few special chat/reasoning tags."""
READS = ()

REASONING_TAGS = {"<think>": 0.17, "</think>": 0.14}
CHAT_TAGS = {"<|im_start|>": -0.05, "<tool_call>": -0.08, "</tool_call>": -0.04, "<tool_response>": 0.04}
DOC_START = -0.03      # first token of a document: the component is slightly negative
EARLY = -0.01          # next few tokens of a document


def step(carry, prefix, upstream):
    n = 0 if carry is None else carry            # tokens already seen in this document
    docs = prefix.document_ids
    if len(docs) > 1 and docs[-1] != docs[-2]:
        n = 0
    tok = prefix.token_strings[-1]
    value = 0.0
    if n == 0:
        value = DOC_START
    elif n < 4:
        value = EARLY
    value += REASONING_TAGS.get(tok, 0.0) + CHAT_TAGS.get(tok, 0.0)
    return n + 1, value

programs.sol:
"""Broad time, personal experience, and real-world noun phrases.

A noun supplies a baseline and sensitivity. Its preceding quantifier,
possessive, or broad adjective supplies the increase: 'all day', 'your
life', 'real world', 'personal data'. A few quantitative and error phrases
contrast with these positive responses. Only the last two tokens are kept;
context resets at document boundaries. Word-shaped token text is matched,
not full sentences; unspaced forms are downweighted. Row-initial possessives
get their ownership strength directly. Unlisted tokens return zero. This
leaves unrelated lexical background and most non-English forms unmodeled.
"""
READS = ()

# (ordinary activation, sensitivity to the preceding modifier)
TIME_UNITS = {
    'time': (0.12, 1.0), 'times': (0.10, 0.9),
    'day': (0.04, 0.95), 'night': (-0.04, 0.9),
    'year': (-0.01, 0.9), 'month': (-0.06, 0.85),
    'week': (-0.14, 0.75), 'hour': (-0.06, 0.5),
    'minute': (0.0, 0.5),
}
EXPERIENCE_WORDS = {
    'life': (0.16, 1.0), 'lives': (0.09, 0.75),
    'body': (0.09, 1.0), 'personal': (0.16, 1.0),
    'world': (0.02, 1.3), 'planet': (-0.06, 1.0), 'earth': (0.17, 0.7),
}
POSSESSIVES = {
    'my': 0.65, 'your': 0.8, 'his': 0.45, 'her': 0.55,
    'their': 0.55, 'its': 0.35, 'our': 1.25,
}
TIME_MODIFIERS = {}
for strength, words in (
    (1.7, 'all'), (0.95, 'each every any'),
    (0.85, 'real present current whole entire'), (0.62, 'same'),
    (0.4, 'one long full'), (0.55, 'per'), (0.28, 'this some more'),
    (0.15, 'the'), (0.12, 'that'), (-0.1, 'a'), (0.1, 'next first'),
):
    TIME_MODIFIERS.update(dict.fromkeys(words.split(), strength))
QUANTIFIER_PHRASES = {
    'all other': 0.53, 'each other': 0.2, 'every single': 0.48,
    'all over': 0.6, 'all around': 0.6, 'each of': 0.2,
    'all of': 0.1, 'all the': -0.12,
}


def response(word, previous, before):
    own = POSSESSIVES.get(previous, 0.0)
    phrase = previous + ' ' + word
    if phrase in QUANTIFIER_PHRASES:
        return QUANTIFIER_PHRASES[phrase]
    if word in TIME_UNITS:
        base, scale = TIME_UNITS[word]
        increase = POSSESSIVES.get(previous, TIME_MODIFIERS.get(previous, 0.0))
        if previous in {'current', 'present'} and word in {'year', 'month', 'week'}:
            increase = 0.25
        if word == 'time':
            if previous in {'the', 'a', 'this', 'that', 'one'} and before == 'at':
                increase += 0.5
            if previous == 'the' and before == 'all':
                increase = 1.35
            if previous in {'at', 'over'}:
                increase = 0.2
        return base + scale * increase
    if word in EXPERIENCE_WORDS:
        base, scale = EXPERIENCE_WORDS[word]
        increase = own
        if previous in {'real', 'daily', 'everyday', 'whole', 'entire'}:
            increase = 1.1
        elif previous in {'human', 'personal', 'natural', 'own'}:
            increase = 0.85
        elif previous == 'the':
            increase = 0.12
            if word == 'world' and before in {'around', 'over', 'across'}:
                increase = 0.5
        elif previous in {"'s", '’s'}:
            increase = 0.2
        if word == 'earth' and previous == 'on':
            increase = 0.33
        return base + scale * increase
    if word in {'data', 'information'}:
        if previous == 'personal':
            return 0.85 if word == 'data' else 0.5
        return 0.03 + 0.5 * own
    if word in {'current', 'local', 'general', 'present', 'natural'}:
        return 0.02 + (0.3 if word == 'natural' else 0.6) * own
    if word in {'single', 'individual'}:
        return 0.6 if previous in {'each', 'every'} else 0.14 + 0.6 * own
    if word in {'number', 'numbers'} and previous == 'real':
        return 0.5 if word == 'numbers' else 0.34
    if word in {'public', 'population'} and previous == 'general':
        return 0.85
    if word in {'rate', 'ratio'}:
        strong = previous in {'same', 'current', 'present', 'real', 'common'}
        return -0.6 if strong else -0.12
    if word in {'gain', 'gains', 'benefit', 'benefits'}:
        return -0.2
    if word in {'error', 'rights', 'injury'} and previous in {'human', 'personal'}:
        return -0.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    previous, before = ('', '') if start else carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip().lower().lstrip('-')
    value = response(word, previous, before)
    if start and word in POSSESSIVES:
        value = POSSESSIVES[word]
    elif not start and not token.startswith((' ', '-')):
        value *= 0.35
    return (doc, word, previous), float(value)

