"""A small lexical sketch of recurring time and life/world responses.

The harvest includes strong responses on words such as “time,” “day,”
“body,” and “world.” This rule gives six such words a modest positive score;
it does not model the context-sensitive peaks or the many other positions.
"""

READS: tuple[str, ...] = ()

TIME_WORDS = {"time", "day", "year"}
LIFE_AND_WORLD_WORDS = {"life", "body", "world"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    word = word.strip(".,!?;:()[]{}\"'“”‘’")
    if word in TIME_WORDS or word in LIFE_AND_WORLD_WORDS:
        return None, 0.23
    return None, 0.0

programs.haiku:
"""Exam-prep vocabulary detector with document context.

This component is quiet on most text. It goes negative on words that name exam and
practice-test material: "exam", "papers", "dumps", "quiz", "chapter", and more weakly
"questions", "practice", "solutions", "PDF", "prep". Inside a document that already
uses exam vocabulary, the dip is larger; a new document starts fresh.
"""

EXAM_WORDS = {"exam", "exams", "examination", "examinations", "papers", "dumps", "quiz",
              "chapter", "考試", "考", "試"}
PRACTICE_WORDS = {"questions", "practice", "solutions", "pdf", "prep", "certification",
                  "quant", "answers", "homework", "official", "mc", "無料", "тест"}
MINOR_WORDS = {"question", "solution", "notes", "exercises", "topics"}

READS = ()


def step(carry, prefix, upstream):
    # carry: (document id, count of exam-vocabulary words so far in this document)
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        seen = 0
    else:
        seen = carry[1]
    word = prefix.token_strings[-1].strip().lower()
    if word in EXAM_WORDS:
        value = -0.87
    elif word in PRACTICE_WORDS:
        value = -0.52
    elif word in MINOR_WORDS:
        value = -0.13
    else:
        value = 0.0
    if value <= -0.5:
        seen += 1
    # Each earlier exam word in this document deepens the dip, up to 3 times.
    value *= 1 + 0.3 * min(seen - 1, 3) if value <= -0.5 else 1.0
    return (doc, seen), float(value)

programs.sol:
"""A lexical response to 'what', end-of-text, and abbreviation-style periods.

End-of-text and the what/whatever word family receive large positive values.
A bare period responds to initials and familiar abbreviations, not ordinary
sentence endings or decimals. Case, attached punctuation and document-start
position modify these responses. Small extra responses cover a leading '#'
and isolated Hungarian double-acute vowels. Short, unspaced Latin-letter
pieces also get a weak signed bias from their vowels and those of the
preceding token: e-like vowels reinforce one another, and a/o/u-like vowels
reverse the sign. Many weaker lexical responses remain unexplained.
"""
import re
import unicodedata

READS = ()

TITLES = {'Mr', 'Mrs', 'Ms', 'Dr', 'St'}
SUFFIXES = {'Jr', 'Sr'}
MONTHS = {
    'Jan', 'Feb', 'Mar', 'Apr', 'Jun', 'Jul', 'Aug',
    'Sep', 'Sept', 'Oct', 'Nov', 'Dec',
}
FORMAL_TITLES = {'Prof', 'Gov', 'Fr', 'Rev', 'Gen', 'Col', 'Capt', 'Sgt', 'Lt'}
COMPANIES = {'Inc', 'Ltd', 'Co', 'Corp', 'Bros'}
ABBREVIATIONS = {
    'No', 'Nos', 'Nr', 'Vol', 'vol', 'pp', 'Ref', 'ref', 'etc', 'ca',
    'approx', 'Mt', 'Pat', 'App', 'Crim', 'Phys', 'Chem', 'Biol', 'Res',
    'Soc', 'Hon', 'Rt', 'Ave', 'ed', 'rev', 'sp', 'nov', 'Sect', 'Sec',
    'Inst', 'Hist', 'Dir', 'Pres', 'Rec', 'Proc', 'Ser', 'Art', 'ch',
    'г', 'ул', 'т', 'д', 'др', 'им', 'ст', 'стр', 'рис', 'см',
}


def period_value(previous, word):
    piece = previous.strip()
    if word in TITLES:
        return 0.72
    if word in SUFFIXES:
        return 0.58
    if word in FORMAL_TITLES or word in COMPANIES:
        return 0.48
    if word in MONTHS:
        return 0.43
    if word.lower() in {'fig', 'figs'}:
        return 0.55 if word == 'FIG' else 0.38
    if word in {'v', 'vs', 'Eq', 'Eqs'}:
        return 0.46
    if word in {'Ct', 'Cir', 'Dist', 'cf', 'Cf', 'Vgl', 'vgl'}:
        return 0.42
    if word == 'al':
        return 0.36
    if word in ABBREVIATIONS:
        return 0.28
    # Internal pieces of abbreviations, such as '.S' in U.S.
    if piece.startswith('.') and piece[1:].isalpha():
        if len(piece) == 2:
            return 0.68 if piece[1].isupper() else 0.36
        return 0.34
    if len(piece) == 1 and piece.isalpha():
        if piece.isupper():
            return 0.44 if previous.startswith(' ') else 0.30
        return 0.20 if previous.startswith(' ') else 0.07
    if word and all(c in 'IVXivx' for c in word):
        return 0.25
    if 2 <= len(word) <= 4 and word.isascii() and word.isupper():
        return 0.20
    return -0.015 if piece.isdigit() else -0.008



def vowel_kind(text):
    """Last vowel: e-like, back (a/o/u), neutral i, or no vowel."""
    if not text.isalpha():
        return None
    if not all('LATIN' in unicodedata.name(c, '') for c in text):
        return None
    for char in reversed(text.lower()):
        if char in 'öőüű':
            return 'rounded_front'
        base = unicodedata.normalize('NFD', char)[0]
        if base in 'eaiou':
            return base
    return 'none'


def vowel_bias(token, previous):
    # A space starts a new word; this bias is for short continuing pieces.
    if token != token.strip() or not token.islower() or len(token) > 6:
        return 0.0
    current = vowel_kind(token)
    previous = previous.strip()
    before = vowel_kind(previous)
    if current is None or before is None:
        return 0.0
    strength = 1.0 if before in {'e', 'rounded_front'} else 0.0
    if before in {'a', 'o', 'u'}:
        strength = -0.4
    response = {
        'e': 0.105, 'a': -0.135, 'i': 0.03, 'o': -0.075,
        'u': -0.12, 'rounded_front': 0.21, 'none': 0.0525,
    }[current]
    shortness = min(1.0, 3.0 / len(token)) ** 2
    shortness *= min(1.0, 3.0 / max(1, len(previous))) ** 2
    return response * strength * shortness


def step(carry, prefix, upstream):
