PEAK = {"dash": 2.5, "paren": 1.6, "semi": 1.2, "colon": 0.8, "hyph": 1.5, "bracket": 0.6}
RAMP = 12      # tokens into a sentence before the mark reaches full strength
WINDOW = 12    # recent tokens used to judge whether the text is running prose
WORD = re.compile(r"\s?[A-Za-z’']+")


def _kind(tok):
    s = tok.strip()
    if s in DASHES or tok.startswith("—") or tok.startswith("–"):
        return "dash"
    if s in PARENS:
        return "paren"
    if s in SEMIS:
        return "semi"
    if s in COLONS:
        return "colon"
    if tok == " -":
        return "hyph"
    if s == "[":
        return "bracket"
    return None


def step(carry, prefix, upstream):
    # carry: (tokens since the sentence started, recent flags: was each token a plain word)
    n, words = carry if carry is not None else (0, ())
    tok = prefix.token_strings[-1]
    new_doc = len(prefix) > 1 and prefix.document_ids[-2] != prefix.document_ids[-1]
    if new_doc:
        n, words = 0, ()
    prev = prefix.token_strings[-2] if len(prefix) > 1 and not new_doc else ""
    kind = _kind(tok)
    value = 0.0
    if kind is not None:
        prose = sum(words[-WINDOW:]) / max(1, len(words[-WINDOW:]))
        after_word = 1.0 if prev[-1:].isalpha() else 0.2
        value = PEAK[kind] * min(1.0, n / RAMP) * prose * after_word
    ends_sentence = tok.rstrip(" ")[-1:] in {".", "!", "?"} or "\n" in tok
    is_word = WORD.fullmatch(tok) is not None
    new_carry = (0 if ends_sentence else n + 1, (words + (is_word,))[-WINDOW:])
    return new_carry, value

