import math

READS = ()
FUNCTION_WORDS = set('''
i you he she it we they me him her us them my your his its our their
this that these those of to in for on with at by from as into about up out
over after under between through before without and or but if so than
because while when although is are was were be been being am have has had
do does did will would can could shall should may might must
'''.split())
DECLARATIONS = set('''
import package namespace class public private def function const var let
using include #include
'''.split())

# Initial value, late value, negative pulse amplitude, decay power.
MARKUP = {
    '<|im_start|>': (-8.916, 0.40, -6.58, 0.85),
    '<|im_end|>': (-4.294, 0.21, -6.94, 0.85),
    '<think>': (-11.51, -0.29, -8.27, 0.80),
    '</think>': (-6.07, 0.29, -4.88, 0.95),
    '<tool_call>': (-5.80, 0.24, -3.17, 0.95),
    '</tool_call>': (-6.04, 0.44, -12.44, 1.05),
    '<tool_response>': (-6.85, 0.16, -4.95, 0.70),
    '</tool_response>': (-8.97, 0.04, -11.17, 0.85),
