ROLES = {'user': -4.992, 'system': -4.824, 'assistant': -4.076}


def opening(token):
    """Opening estimate and whether the token separates a content phrase."""
    w = token.strip()
    n, spaced = min(len(w), 10), token[:1].isspace()
    if not w:
        return (-0.07 if '\n' in token else 0.5/math.sqrt(max(len(token), 1))), True
    if token.startswith('<|'):
        return 0.0, True
    if w.isascii() and w.isdecimal():
        return 0.48, True
    if w.lower() in {'a', 'an', 'the'}:
        if spaced:
            value = 0.43 if w == 'the' else 0.10 if w == 'The' else 0.03
        elif w.lower() == 'the':
            value = 1.61 if w == 'The' else 0.82 if w == 'the' else 0.28
        else:
            value = 0.79 if w[0].isupper() else 0.31
        return value, True
    if w.lower() in FUNCTION_WORDS:
        if spaced:
            value = -0.05 if w.islower() else -0.20
        else:
            value = 0.22 if w.islower() else 0.52 if w.isupper() else 0.41
        return value, True
    if w.lower() in DECLARATIONS:
        return (-0.57 if spaced else 1.21), False
    if all(not c.isalnum() for c in w):
        if set(w) == {'#'}:
            return 1.55 + 0.3*min(n, 3), True
        if w in {'(', '[', '{'}:
            return (0.55 if spaced else 1.1), True
        if w in {')', ']', '}'}:
            return 0.0, True
        return (0.1 if '\n' in token else 0.3), True
    if not w.isascii():
        if any('\u4e00' <= c <= '\u9fff' for c in w):
            return 0.26 - 0.47*min(n, 4), False
        return 0.19 - 0.22*n, False
    if not w.isalpha():
        return -0.36, False
    if n == 1:
        return (-0.19 if spaced else 0.39), False
    if w[0].isupper():
        return (-0.35 - 0.05*n if spaced else 0.36 - 0.06*n), False
    past = float(w.endswith('ed'))
