            (0.25 - 0.095*n - 0.30*past)), False


def step(carry, prefix, upstream):
    doc, token = int(prefix.document_ids[-1]), prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, unfinished, strength, decay, previous = 0, True, 1., 0.8, ''
    else:
        _, position, unfinished, strength, decay, previous = carry
        position += 1
    initial, separator = opening(token)
    if position == 0:
        value = initial
        if token[:1].isspace() and initial < -0.4:
            strength, decay = 0.94, 0.80
        elif not token.isascii():
            strength, decay = 0.55, 0.875
        else:
            strength, decay = 0.21, 0.975
    else:
        value = min(initial, 0.)*strength*decay**position if unfinished else 0.
    if token in MARKUP:
        start, late, size, power = MARKUP[token]
        value = start if position == 0 else late + size/(position + 1)**power
        if token == '<|im_start|>' and position == 1 and previous == '\n':
            value = -1.416
    elif previous == '<|im_start|>' and token in ROLES:
        value = ROLES[token] if position == 1 else (
            0.075 - 8.28/(position + 1)**0.95 if token == 'user' else 0.)
    state = (doc, position, unfinished and not separator, strength, decay, token)
    return state, float(value)

