"""Approximate document-opening and literal-escaping responses.

Training examples have large positive responses at document openings, especially
metadata labels and source-file boilerplate. These lexical classes, spelling
shape, and a few opening delimiters determine the opening prediction. Outside
the opening, backslash clusters are negative; even-length clusters are stronger.
The beginning of a Unix shebang path is positive too. Identical repetitions of
an opening middle-dot, four-caret, or carriage-return token keep its response.
Other body text is zero: diffuse, token-specific fluctuations are not modeled.
"""

import re

READS = ()

# Declarations/imports that commonly begin a source file.
IMPORTS = {'from', 'using', 'package', 'require'}
DECLARATIONS = {'namespace', 'export', 'const', 'def', 'class',
                'public', 'private', 'function', 'void', 'theorem'}
NAVIGATION = {'Click', 'View', 'Views', 'Read', 'Available', 'Expand',
              'Use', 'Download', 'Home', 'Search', 'Contents'}
FUNCTION_WORDS = {'the', 'a', 'an', 'and', 'but', 'of', 'on', 'in', 'to',
                  'for', 'from', 'as', 'at', 'that', 'this', 'it', 'you',
                  'we', 'they', 'he'}
LABELS = {'Subject', 'Answer', 'Name', 'Description', 'Summary',
          'Content', 'Date', 'Author', 'Keywords', 'Abstract', 'Introduction'}


def opening(s):
    if s == 'Title':
        return 2.40
    if s == 'Question':
        return 0.91
    if s in {'uploaded', 'Uploaded'}:
        return 1.90
    if s in {'Show', 'Showing'}:
        return 1.08
    if s in NAVIGATION:
        return 0.62
    if s in {'What', 'How', 'Why', 'Where'}:
        return 0.45
    if s == 'FIELD':
        return 1.40
    if s in LABELS:
        return 0.40
    if s == 'import':
        return 1.26
    if s in IMPORTS:
        return 0.75
    if s in DECLARATIONS:
        return 0.55
    if s == "'use":
        return 1.44
    if s == '//\n':
        return 2.53
    if s.startswith('/*'):
        return 1.07 if '\n' in s else 1.20
    if s == '//':
        return 0.79
    if s == '#![':
        return 0.69
    if s.startswith('#!'):
        return 1.05
    if s == '#':
        return 0.23
    if s.startswith('#') and len(s) > 1 and s[1].isalpha():
        return 0.85
    if s in {'##', '###'}:
        return 1.11
    if s.startswith('---'):
        return 0.85
    if s in {'<?', '{', '"""\n'}:
        return 1.02
    if s == '<!':
        return 2.78
    if s.startswith('<|'):
        return 0.0
    if s == '\r':
        return 2.80
    if s == '··':
        return 0.87
    if s == '^^^^':
        return 1.61
    if '\\\\' in s:
        return escape_value(s, initial=True)
    if '\ufffd' in s:
        return 0.34
    if not s or s.isspace():
        return 0.03
    if s[0].isspace():
        return -0.08 if s.strip() in FUNCTION_WORDS else 0.055
    if s.isascii() and s.isalpha():
        if len(s) == 1:
            return 0.03 if s.isupper() else -0.03
        if s.isupper():
            return 0.35 if len(s) >= 3 else 0.08
        if s[0].isupper():
            return 0.22 if len(s) >= 3 else 0.14
        return 0.11
    if s[0].isupper():
        return 0.18
    if s[0].islower():
        return 0.08
    if s[0].isdigit():
        return 0.03
    return 0.10


def escape_value(s, initial=False):
    """Even backslash runs are strongly negative; odd runs less so."""
    longest = max(map(len, re.findall(r'\\+', s)))
    if longest % 2:
        return -0.07 if initial else -0.22
    if initial:
        return -0.41
    return -0.70 if s.endswith('\\') else -0.40


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        return (doc, s, True, 0), opening(s)
    _, first, uniform, position = carry
    position += 1
    was_uniform = uniform
    uniform = uniform and s == first
    value = 0.0
    if uniform and s in {'··', '\r', '^^^^'}:
        value = opening(s)
    elif was_uniform and first == '\r' and s.startswith('\r\r'):
        value = 0.79
    elif '\\\\' in s:
        value = escape_value(s)
    elif s == '\r':
        value = 0.22
    elif first == '#!/' and position <= 3:
        # The Unix interpreter path in an opening shebang line.
        if s == 'usr':
            value = 0.84
        elif s == '/bin':
            value = 1.35
        elif s == 'bin':
            value = 0.27
        elif s in {'/sh', '/bash', '/env'}:
            value = 0.39
    return (doc, first, uniform, position), value

"""Predict responses to familiar programming constructions.

The predictor recognizes the second half of qualified names (std::, java.util,
stdio.h, github.com), file paths, and punctuation beginning quoted arguments.
