"""layers.0.mlp.down_proj:3124: a qualified-name continuation detector.

The component writes into the residual stream mainly on the token that continues a
qualified name, the part after a namespace, package or library root:
  - `::` after `std` (std::cout, std::string): strongest, about 4.3
  - `::` elsewhere (C++ scope, Rust paths, Python test ids): about 1.3
  - a dotted or slashed name segment (`.util` in java.util, `.h` in <stdio.h>,
    `.out` in System.out, `/bin` in /usr/local/bin, `_modules` in node_modules):
    about 1.0 when the root before it is a known namespace or library, about 0.1 otherwise
  - code punctuation that opens an argument or attribute (`="`, `('`, `("`, `->`,
    ` import`): about 0.5
Everything else (ordinary words, spaces, plain dots, commas, brackets) predicts 0.
The values are the mean activation of each group on 4000 training rows.
"""

ROOTS = {
    "std", "System", "java", "javax", "org", "com", "node", "console", "env", "os",
    "sys", "io", "net", "util", "github", "apache", "springframework", "Math", "tf",
    "JSON", "DB", "Debug", "Convert", "Array", "Vec", "String",
}
JOINERS = {'="', "('", '("', "->", " import"}

READS = ()


def _word(s):
    return len(s) > 1 and s[1:].replace("_", "").isalnum()


def _base(s):
    return s.strip().lstrip("(\t[{").strip()


def _is_segment(s):
    """A dotted or slashed name segment, or the `_modules` attribute."""
    return s == "_modules" or (s[:1] in (".", "/") and _word(s))


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = _base(prefix.token_strings[-2]) if same_doc else ""
    root = prev in ROOTS
    if cur == "::":
        value = 4.3 if prev == "std" else (1.4 if root else 1.3)
    elif _is_segment(cur):
        value = 1.0 if root else 0.1
    elif cur in JOINERS:
        value = 0.5
    else:
        value = 0.0
    return carry, float(value)

