# Shared class strengths deliberately omit many small lexical differences.
READS = ()

STRONG_LINKERS = {
    'thus': 6.1, 'hence': 5.8, 'so': 5.3, 'therefore': 5.3,
    'consequently': 5.4, 'yet': 5.0, 'thereby': 4.8, 'then': 4.25,
    'how': 4.0, 'what': 4.0, 'why': 4.2, 'also': 3.85, 'now': 3.7,
