                       'particularly sometimes potentially moreover '
                       'furthermore additionally'.split())
QUALIFICATION = set('later thereafter accordingly hopefully eventually '
                    'perhaps often even more again maybe ultimately '
                    'indeed here similarly specifically occasionally'.split())
CLAUSE_WORDS = set('that which where who when whether if this such'.split())
AUXILIARIES = set('is are was were can could may might will would should '
                  'do does did'.split())
PREPOSITIONS = set('in for with as of at by on to from without after before '
                   'around among beyond during over up'.split())
REFERENCE_WORDS = set('these those its their other some any all one many much '
                      'most less both no her it you'.split())


def lexical_strength(word):
    if word in STRONG_LINKERS:
        return STRONG_LINKERS[word]
    for words, value in ((ADDITION_SEQUENCE, 3.5), (QUALIFICATION, 2.7),
                         (CLAUSE_WORDS, 2.1), (AUXILIARIES, 1.3),
                         (PREPOSITIONS, 0.95), (REFERENCE_WORDS, 0.65)):
        if word in words:
            return value
    if word == 'not':
        return 1.65
    if word in {'a', 'i', 'he', 'she'}:
        return -0.2
    return 0.4 if word.endswith('ly') else -0.07


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    previous, before = carry[1:] if carry and carry[0] == doc else ('', '')
    conjunction = previous.strip().lstrip('-.').lower()
    word = token.strip().lstrip('-_')
    value = 0.0
    if conjunction in {'and', 'but', 'or'}:
        attached = token and not token[0].isspace() and token.isalpha()
        # This lexical trigger also catches names/stems such as Andr-/Ande-.
        if attached:
            if conjunction != 'and':
                value = 0.8 if conjunction == 'but' else 0.25
            elif previous.startswith(' '):
                value = 3.5 if previous.strip() == 'And' else (
                    3.7 if word.startswith(('r', 'e')) else 1.5)
            else:
                value = 2.0 if word.startswith(('r', 'e')) else 1.0
        elif word.lower() == '/or' and conjunction == 'and':
            value = 6.6
        elif word == ',':
            value = 1.15
        elif word.isdigit():
            value = 0.45
        else:
            value = lexical_strength(word.lower())
            if word != word.lower() and word != 'I':
                value *= 0.4
        if conjunction == 'but':
            value = 0.25 * max(value, 0.0)
        elif conjunction == 'or':
            value *= 0.3
        elif previous.strip().startswith('-'):
            value *= 0.65
        elif previous.strip() != 'and' and not attached:
            value *= 0.85
    elif before.strip().lower() == 'and' and word in STRONG_LINKERS:
        value = 0.16 * STRONG_LINKERS[word]
    return (doc, token, previous), float(value)

