SUFFIXES = {
    "ular": 0.63,
    "iveness": 0.50,
    "ness": 0.52,
    "ous": 0.71,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]

    same_doc = len(prefix) > 1 and (
        prefix.document_ids[-2] == prefix.document_ids[-1]
    )
    if token == " now" and same_doc:
        if prefix.token_strings[-2].strip().lower() == "right":
            return None, -0.84

