"""Detect characteristic spellings for written material, especially 文 and text.

Return positive values for a small multilingual vocabulary of text, files,
documents, writing, and language names, and a negative value for end-of-text.
Case and punctuation distinguish code identifiers from prose. For split words,
use the preceding token (only within the same document): 文 in 上下文 ('context')
and 注文 ('order'), 문 in Korean question/order/specialist words, and LaTeX
backslash + text have smaller responses. Unrecognized tokens return zero.
"""
READS = ()

# Approximate responses shared by related words and translations.
GROUPS = (
    (1.10, 'file files paper papers doc docs document documents literature'),
    (0.80, 'article articles txt documentation documentary manuscript literary '
           'essay essays written writer writers paragraph paragraphs binary'),
    (0.50, 'writing sentence culture'),
    (0.75, 'cultural cultured'),
    (0.25, 'write wrote writes'),
    (1.00, 'english'),
    (0.85, 'chinese'),
    (0.65, 'french arabic'),
    (1.75, 'texto texte текст'),
    (1.15, 'документ документов'),
    (0.80, 'arquivo файл 書 书 ファイル'),
    (3.75, 'văn 中文 英文 原文 全文 人文 图文'),
    (3.15, '文章 文字 语文 范文 文体'),
    (1.70, '文化 文艺 文明 文件 纹 紋'),
    (4.60, '本文'),
)
LEXICON = {w: gain for gain, words in GROUPS for w in words.split()}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == '<|endoftext|>':
        return None, -0.95
    previous = ''
    if len(prefix.token_strings) > 1:
        if prefix.document_ids[-2] == prefix.document_ids[-1]:
            previous = prefix.token_strings[-2]
    spelling = token.strip()
    word = spelling.lstrip('_.-/;(,\"').lower()
    if word == '文':
        value = 7.10 if token == '文' else 6.00
        if previous.endswith('上下'):
            value = 1.40
        elif previous.endswith('注'):
            value = 5.00
        elif previous.endswith(('論', '论', '條', '条')):
            value = 4.10
    elif word == '문':
        value = 4.45 if token == '문' else 3.60
        if previous.endswith(('질', '주', '전')):
            value = 2.90
    elif word == 'text':
        value = 1.80
        if token == 'text':
            value = 1.26 if previous.endswith('\\') else 1.93
        elif spelling.startswith(('_', '-', '.', '/')):
            value = 2.30
        elif spelling.startswith('('):
            value = 1.60
    elif word in ('gettext', 'settext', 'texts', 'textual'):
        value = 1.50
    else:
        word = word.removeprefix('的')
        value = LEXICON.get(word, 0.0)
        if not value and '文' in word:
            value = 1.30 if '文化' in word else 2.20
        if word == 'file' and token == 'file':
            value = 0.80
        elif word == 'file' and spelling.startswith('_'):
            value = 0.90
    return None, float(value)

