"""Written-text detector: a model of layer 0 MLP component 3128.

The component writes a positive signal when the current token names written text,
documents, files or writing (text, file, document, paper, article, writing, literature,
and their translations; the Chinese character 文 'writing/text' and its compounds), and a
fixed negative signal on the end-of-text token. Everything else is about 0.
"""
READS = ()

END_OF_TEXT = "<|endoftext|>"

# Whole words (lower case, edge punctuation stripped) and their typical activation.
WORDS = {
    "file": 1.0, "files": 1.0, "doc": 1.2, "docs": 1.2, "document": 1.1,
    "documents": 1.1, "documentation": 0.9, "paper": 1.1, "papers": 1.2,
    "article": 0.9, "articles": 0.9, "essay": 0.7, "essays": 0.7, "written": 0.8,
    "writing": 0.5, "writer": 0.6, "writers": 0.7, "literature": 1.0, "literary": 0.8,
    "manuscript": 0.8, "binary": 0.9, "english": 0.9, "chinese": 0.9, "french": 0.7,
    "arabic": 0.7, "textual": 1.5, "txt": 0.8, "texto": 1.8, "texte": 2.0, "texts": 1.2,
    "текст": 1.6, "документ": 1.2, "документов": 1.2, "documento": 1.2, "книга": 0.9,
    "書": 0.8, "书": 0.8, "culture": 0.5, "cultural": 0.7,
}

def word_of(tok):
    return tok.strip(" _.-\t/(\n\"'").lower()

def text_value(tok):
    w = word_of(tok)
    if w in WORDS:
        return WORDS[w]
    if "text" in w and "context" not in w:
        return 1.6          # text, Text, _text, getText, .txt-like
    if "file" in w and "profile" not in w:
        return 1.0
    return 0.0

def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if tok == END_OF_TEXT:
        return carry, -0.95
    if "文" in tok:
        return carry, 6.0 if tok.strip(" ") == "文" else 3.0   # the character alone, or a compound
    if tok.strip(" ") in ("문", "문자", "문서"):
        return carry, 4.0       # Korean 'writing / document'
    return carry, text_value(tok)

