CIRCUMFLEX = {'â': 2.16, 'ê': 0.83, 'î': 1.2, 'ô': 0.37, 'û': 0.78}
UPPER_CIRCUMFLEX = {'Â': 0.9, 'Ê': 0.65, 'Î': 0.5, 'Ô': 0.44, 'Û': 0.2}
CARON = {'ǎ': 1.13, 'ě': 0.6, 'ǐ': 1.15, 'ǒ': 1.7, 'ǔ': 1.0}
LATVIAN_CONSONANTS = {'ņ': 2.25, 'ļ': 2.3, 'ķ': 1.1}
