    'ā': 4.9, 'ē': 2.7, 'ī': 2.55, 'ō': 2.5, 'ū': 2.7,
    'Ā': 3.6, 'Ē': 2.0, 'Ō': 1.9, 'Ū': 2.0,
}
COME_WITH = {'come': -0.68, 'comes': -0.51, 'came': -0.38, 'coming': -0.59}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    reset = carry is None or carry[0] != doc
    if reset:
        previous, before_previous = '', ''
    else:
        _, previous, before_previous = carry
    token = prefix.token_strings[-1]
    letter = token.strip()
    value = 0.0

    if letter.lower() in MACRON:
        value = MACRON[letter.lower()]
        if letter == 'Ā':
            value = 4.1
        elif letter == 'ā' and previous[-1:].isupper():
            value += 0.8
    elif letter in CIRCUMFLEX or letter in UPPER_CIRCUMFLEX:
        value = CIRCUMFLEX.get(letter, UPPER_CIRCUMFLEX.get(letter, 0.0))
        if token.startswith(' '):
