    ':': 3.7,
    '?': 3.5,
    '!': 2.6,
    ',': 3.1,
    ';': 2.85,
    ')': 2.55,
    ']': 1.9,
    '}': 1.2,
    '(': 0.95,
    '[': 1.35,
    '{': 0.4,
    '$': 0.55,
    '*': 0.9,
    '=': 1.5,
    '-': 1.7,
    '>': 1.8,
    '。': 3.5,
}


