SHORT_FUNCTION_WORDS = {
    'a', 'an', 'as', 'at', 'be', 'by', 'do', 'he', 'if',
    'in', 'is', 'it', 'me', 'my', 'no', 'of', 'on', 'or',
    'so', 'to', 'up', 'us', 'we', 'I',
