            elif before_previous.endswith('\\'):
                value = -0.35
            elif previous[-1] in '.!?;:':
                value = 0.65
        elif '\\' in before:
            value = 2.05
        elif before[-1] in "\"'`":
            value = 0.7 if before[0].isspace() else 1.45
        else:
            value = ESCAPE_AFTER.get(before[-1], 1.2)
            if before[-1] in '([{*' and before[0].isspace():
                value += 0.5
            if before.endswith('...'):
