            elif not previous:
                value -= 1.3
            elif previous[-1].isdigit() or previous[-1].isspace():
                value -= 0.15
            elif previous[-1].isalpha():
                if '\\' in previous:
                    value -= 0.2
                elif len(previous.strip()) >= 4 and previous[0].isspace():
                    value += 0.18
                elif len(previous.strip()) <= 2 and not previous[0].isspace():
                    value -= 0.1
