        elif before.isspace():
            value = 0.65 if not previous or previous[-1].isspace() else 2.0
        else:
            value = 2.85
            if not before and previous:
                if previous[-1].isspace():
                    value = 0.65 if previous.rstrip().endswith('>') else 1.4
                elif previous[-1].isdigit():
                    value = 2.4
