"""Approximate a local number-boundary and spelling-transition response.

Zero beginning a numeric run is positive; internal zeros are near zero.
Preceding decimal punctuation weakens it. Escape starts and some letter-
digit suffixes are negative. After u/у, a/e-like continuations are positive
(stronger after hu, weaker after qu); other vowels are negative. A split
historical long-s letter is negative too. Levels are rounded training
averages, not an attempt to recover every word-specific exception.
"""
import re
import unicodedata

READS = ()
DIGITS = '0123456789'


def response(token, previous):
    last = previous[-1:]
    lower = previous.lower()
    if len(token) == 1 and token in DIGITS:
        zero = token == '0'
        if last and last in DIGITS:
            return 0.005
        if lower.endswith('u'):
            if last == 'u':
                return -5.2 if zero else -2.2
            return -2.6 if zero else -1.0
        if previous.endswith('\\x'):
            return -2.68 if zero else -2.0
        if re.search(r'x[a-f]$', lower):
            if zero:
                return 0.0
            if last.lower() == 'c':
                return -1.32 if lower.endswith('\\xc') else -0.55
            return -0.72 if last.lower() == 'e' else 0.0
        if last == '\\':
            return -1.4 if zero else -0.3
        if previous == 'x':
            return -0.73
        if lower.endswith(('x', 'v')):
            return -0.05 if zero else -0.30
        if lower.endswith('y'):
            return 0.7 if zero else -0.25
        if previous.endswith('&#'):
            return -0.86
        if last == '%':
            return 0.39 if zero else -0.51
        if not zero:
            return -0.091 if last == '.' else -0.005
        if not previous:
            return 0.11
        if last.isspace():
            return 1.33
        if last in '([{':
            return 1.47
        if last == '.':
            return 0.30
        if last == ',':
            return 0.83
        if last == ':':
            return 1.03
        if last == '=':
            return 1.24
        if last.isalpha():
            return 0.93
        return 1.15

    if lower.endswith(('u', 'у')) and token and token[0].isalpha():
        first = unicodedata.normalize('NFD', token[0].lower())[0]
        if first in 'aаeеэ':
            if lower.endswith('hu'):
                return 2.45
            if lower.endswith('qu'):
                return 0.155 if first == 'a' else 0.51
            return 1.13
        if first in 'iиoоuу':
            return -0.35
        return -0.135
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = response(token, previous)
    # Decode a split multibyte letter only when both pieces look invalid alone.
    if token == '\ufffd' and previous.endswith('\ufffd'):
        if prefix.text_prefixes[-1].endswith('ſ'):
            value = -1.66
    return (doc, token), value

